import { useState, useRef, useEffect } from 'react';
import { cn } from '../../lib/cn';
import {
  Briefcase, FolderKanban, CheckSquare, CheckCircle, FileText, FileEdit,
  BookOpen, BarChart3, ScrollText, UserPlus, Building2, Shield, Lock,
  Sparkles, MessageSquare, Zap, User, ChevronRight,
} from 'lucide-react';
import { Badge } from '../ui/Badge';
import { type ActivityItem } from './ActivityTypes';

interface ActivityCardProps {
  item: ActivityItem;
  onSelect: (item: ActivityItem) => void;
}

const iconMap: Record<string, typeof Briefcase> = {
  briefcase: Briefcase, 'folder-kanban': FolderKanban, 'check-square': CheckSquare,
  'check-circle': CheckCircle, 'file-text': FileText, 'file-edit': FileEdit,
  'book-open': BookOpen, 'bar-chart-3': BarChart3, 'scroll-text': ScrollText,
  'user-plus': UserPlus, 'building-2': Building2, shield: Shield, lock: Lock,
  sparkles: Sparkles, 'message-square': MessageSquare, zap: Zap, user: User,
};

const iconBg: Record<string, string> = {
  briefcase: 'bg-accent-50 text-accent-600 dark:bg-accent-100/10 dark:text-accent-300',
  'folder-kanban': 'bg-info-50 text-info-600 dark:bg-info-100/10 dark:text-info-300',
  'check-square': 'bg-warning-50 text-warning-600 dark:bg-warning-100/10 dark:text-warning-300',
  'check-circle': 'bg-success-50 text-success-600 dark:bg-success-100/10 dark:text-success-300',
  'file-text': 'bg-accent-50 text-accent-600 dark:bg-accent-100/10 dark:text-accent-300',
  'file-edit': 'bg-warning-50 text-warning-600 dark:bg-warning-100/10 dark:text-warning-300',
  'book-open': 'bg-info-50 text-info-600 dark:bg-info-100/10 dark:text-info-300',
  'bar-chart-3': 'bg-success-50 text-success-600 dark:bg-success-100/10 dark:text-success-300',
  'scroll-text': 'bg-accent-50 text-accent-600 dark:bg-accent-100/10 dark:text-accent-300',
  'user-plus': 'bg-success-50 text-success-600 dark:bg-success-100/10 dark:text-success-300',
  'building-2': 'bg-info-50 text-info-600 dark:bg-info-100/10 dark:text-info-300',
  shield: 'bg-danger-50 text-danger-600 dark:bg-danger-100/10 dark:text-danger-300',
  lock: 'bg-warning-50 text-warning-600 dark:bg-warning-100/10 dark:text-warning-300',
  sparkles: 'bg-accent-50 text-accent-600 dark:bg-accent-100/10 dark:text-accent-300',
  'message-square': 'bg-info-50 text-info-600 dark:bg-info-100/10 dark:text-info-300',
  zap: 'bg-warning-50 text-warning-600 dark:bg-warning-100/10 dark:text-warning-300',
  user: 'bg-surface-2 text-text-secondary dark:bg-surface-2',
};

const statusBadge: Record<string, { label: string; tone: 'success' | 'warning' | 'info' } | null> = {
  completed: { label: 'Completed', tone: 'success' },
  'in-progress': { label: 'In Progress', tone: 'warning' },
  pending: { label: 'Pending', tone: 'info' },
};

export function ActivityCard({ item, onSelect }: ActivityCardProps) {
  const Icon = iconMap[item.icon] || FileText;
  const bg = iconBg[item.icon] || iconBg['file-text'];
  const status = item.status ? statusBadge[item.status] : null;

  return (
    <button
      type="button"
      onClick={() => onSelect(item)}
      aria-label={`View details: ${item.title}`}
      className="group relative flex items-start gap-4 rounded-xl border border-border-subtle bg-elevated p-4 sm:p-5 text-left w-full transition-all duration-150 hover:shadow-cx-sm hover:-translate-y-0.5"
    >
      <div className={cn('flex h-10 w-10 shrink-0 items-center justify-center rounded-xl transition-colors', bg)}>
        {Icon && <Icon className="h-5 w-5" />}
      </div>
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-2">
          <p className="text-body font-semibold text-text-primary truncate">{item.title}</p>
          {status && <Badge variant="soft" tone={status.tone} className="text-2xs">{status.label}</Badge>}
        </div>
        <p className="text-caption text-text-secondary mt-0.5 line-clamp-2">{item.description}</p>
        <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-2 text-2xs text-text-tertiary">
          <span className="flex items-center gap-1">
            <span className="flex h-4 w-4 items-center justify-center rounded-full bg-surface-2 text-2xs font-bold text-text-secondary">{item.actor.avatar}</span>
            {item.actor.name}
          </span>
          {item.workspace && <span>{item.workspace}</span>}
          {item.department && <span>{item.department}</span>}
          {item.project && <span>{item.project}</span>}
          <span className="ml-auto">{item.timestamp}</span>
        </div>
      </div>
      <ChevronRight className="h-4 w-4 text-text-tertiary shrink-0 mt-2 opacity-0 group-hover:opacity-100 transition-opacity duration-150" />
    </button>
  );
}

import { useEffect, useRef } from 'react';
import { X, ExternalLink, Calendar, Clock, User, Briefcase, Building2, FolderKanban, FileText, Tag } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { cn } from '../../lib/cn';
import { IconButton } from '../ui/IconButton';
import { Badge } from '../ui/Badge';
import { type ActivityItem } from './ActivityTypes';

interface ActivityDetailDrawerProps {
  item: ActivityItem | null;
  open: boolean;
  onClose: () => void;
}

export function ActivityDetailDrawer({ item, open, onClose }: ActivityDetailDrawerProps) {
  const navigate = useNavigate();
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [open, onClose]);

  useEffect(() => {
    if (open) ref.current?.focus();
  }, [open]);

  if (!item) return null;

  return (
    <>
      {open && (
        <div className="fixed inset-0 z-40 bg-text-primary/30 dark:bg-black/50 backdrop-blur-sm animate-fade-in" onClick={onClose} />
      )}
      <div
        ref={ref}
        role="dialog"
        aria-modal="true"
        aria-label={`Activity details: ${item.title}`}
        tabIndex={-1}
        className={cn(
          'fixed right-0 top-0 z-50 h-full w-full max-w-lg border-l border-border-subtle bg-elevated shadow-cx-xl transition-transform duration-300 flex flex-col',
          open ? 'translate-x-0' : 'translate-x-full',
        )}
      >
        <div className="flex items-center justify-between px-5 py-4 border-b border-border-subtle">
          <p className="text-section font-semibold text-text-primary">Activity Details</p>
          <IconButton label="Close" variant="ghost" size="sm" onClick={onClose}>
            <X className="h-4 w-4" />
          </IconButton>
        </div>

        <div className="flex-1 overflow-y-auto px-5 py-5 space-y-6">
          <div className="space-y-2">
            <p className="text-body-lg font-semibold text-text-primary">{item.title}</p>
            <p className="text-body text-text-secondary leading-relaxed">{item.description}</p>
          </div>

          <div className="grid grid-cols-2 gap-3">
            {item.actor && (
              <div className="rounded-lg bg-surface p-3">
                <div className="flex items-center gap-2 text-caption text-text-tertiary mb-1">
                  <User className="h-3.5 w-3.5" />
                  <span>Actor</span>
                </div>
                <p className="text-caption font-medium text-text-primary">{item.actor.name}</p>
              </div>
            )}
            {item.workspace && (
              <div className="rounded-lg bg-surface p-3">
                <div className="flex items-center gap-2 text-caption text-text-tertiary mb-1">
                  <Briefcase className="h-3.5 w-3.5" />
                  <span>Workspace</span>
                </div>
                <p className="text-caption font-medium text-text-primary">{item.workspace}</p>
              </div>
            )}
            {item.department && (
              <div className="rounded-lg bg-surface p-3">
                <div className="flex items-center gap-2 text-caption text-text-tertiary mb-1">
                  <Building2 className="h-3.5 w-3.5" />
                  <span>Department</span>
                </div>
                <p className="text-caption font-medium text-text-primary">{item.department}</p>
              </div>
            )}
            {item.project && (
              <div className="rounded-lg bg-surface p-3">
                <div className="flex items-center gap-2 text-caption text-text-tertiary mb-1">
                  <FolderKanban className="h-3.5 w-3.5" />
                  <span>Project</span>
                </div>
                <p className="text-caption font-medium text-text-primary">{item.project}</p>
              </div>
            )}
            <div className="rounded-lg bg-surface p-3">
              <div className="flex items-center gap-2 text-caption text-text-tertiary mb-1">
                <Clock className="h-3.5 w-3.5" />
                <span>Timestamp</span>
              </div>
              <p className="text-caption font-medium text-text-primary">{item.timestamp}</p>
            </div>
            {item.status && (
              <div className="rounded-lg bg-surface p-3">
                <div className="flex items-center gap-2 text-caption text-text-tertiary mb-1">
                  <Tag className="h-3.5 w-3.5" />
                  <span>Status</span>
                </div>
                <Badge variant="soft" tone={item.status === 'completed' ? 'success' : item.status === 'in-progress' ? 'warning' : 'info'}>
                  {item.status}
                </Badge>
              </div>
            )}
          </div>

          {item.resources && item.resources.length > 0 && (
            <div className="space-y-2">
              <p className="text-caption font-semibold text-text-primary">Related Resources</p>
              <div className="space-y-1.5">
                {item.resources.map((r, i) => (
                  <button
                    key={i}
                    type="button"
                    onClick={() => { navigate(r.path); onClose(); }}
                    className="flex w-full items-center gap-2 rounded-lg border border-border-subtle bg-surface p-2.5 text-left hover:shadow-cx-sm transition-all duration-150"
                  >
                    <FileText className="h-4 w-4 text-accent-600 dark:text-accent-400 shrink-0" />
                    <span className="flex-1 text-caption font-medium text-text-primary truncate">{r.title}</span>
                    <Badge variant="soft" tone="neutral" className="text-2xs">{r.type}</Badge>
                    <ExternalLink className="h-3.5 w-3.5 text-text-tertiary shrink-0" />
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </>
  );
}

import { cn } from '../../lib/cn';

interface ActivityTimelineProps {
  children: React.ReactNode;
}

export function ActivityTimeline({ children }: ActivityTimelineProps) {
  return (
    <div className="relative">
      {children}
    </div>
  );
}

interface ActivityTimelineGroupProps {
  label: string;
  children: React.ReactNode;
}

export function ActivityTimelineGroup({ label, children }: ActivityTimelineGroupProps) {
  return (
    <div className="relative pb-8">
      <div className="sticky top-0 z-10 bg-canvas pb-3 pt-2">
        <div className="flex items-center gap-3">
          <div className="h-px flex-1 bg-border-subtle" />
          <p className="text-caption font-semibold text-text-tertiary uppercase tracking-wider">{label}</p>
          <div className="h-px flex-1 bg-border-subtle" />
        </div>
      </div>
      <div className="flex flex-col gap-3">
        {children}
      </div>
    </div>
  );
}

import { useState, type ReactNode } from 'react';
import { Outlet, useNavigate, useLocation } from 'react-router-dom';
import { Sparkles, BarChart3, ScrollText, BookOpen, FileText, Clock, X } from 'lucide-react';
import { cn } from '../../lib/cn';
import { AIHeader } from './AIHeader';
import { AISearchInput } from './AISearchInput';

const aiNavItems = [
  { id: 'ai', label: 'AI Dashboard', icon: Sparkles, path: '/app/ai' },
  { id: 'ai-history', label: 'History', icon: Clock, path: '/app/ai/history' },
  { id: 'ai-analytics', label: 'Analytics AI', icon: BarChart3, path: '/app/ai/analytics' },
  { id: 'ai-handover', label: 'Handover AI', icon: ScrollText, path: '/app/ai/handover' },
  { id: 'ai-knowledge', label: 'Knowledge AI', icon: BookOpen, path: '/app/ai/knowledge' },
  { id: 'ai-reports', label: 'Report Viewer', icon: FileText, path: '/app/ai/reports' },
];

export function AILayout() {
  const navigate = useNavigate();
  const location = useLocation();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [rightPanelOpen, setRightPanelOpen] = useState(false);

  const isActive = (path: string) => location.pathname === path;

  return (
    <div className="flex gap-0 lg:gap-6">
      {/* Mobile sidebar trigger */}
      <button
        type="button"
        onClick={() => setSidebarOpen(true)}
        aria-label="Open AI navigation"
        aria-expanded={sidebarOpen}
        aria-haspopup="dialog"
        className="lg:hidden fixed bottom-6 right-6 z-50 flex h-12 w-12 items-center justify-center rounded-full bg-accent-600 text-white shadow-cx-lg hover:bg-accent-700 transition-colors"
      >
        <Sparkles className="h-5 w-5" />
      </button>

      {/* Mobile backdrop */}
      {sidebarOpen && (
        <div className="fixed inset-0 z-40 bg-text-primary/40 dark:bg-black/60 backdrop-blur-sm animate-fade-in lg:hidden" aria-hidden="true" onClick={() => setSidebarOpen(false)} />
      )}

      {/* AI Sidebar navigation */}
      <div
        role={sidebarOpen ? 'dialog' : undefined}
        aria-modal={sidebarOpen ? 'true' : undefined}
        aria-label="AI navigation"
        className={cn(
          'fixed inset-y-0 left-0 z-50 w-64 shrink-0 bg-elevated border-r border-border-subtle overflow-y-auto transition-transform duration-300 lg:sticky lg:top-0 lg:z-0 lg:block lg:h-[calc(100vh-7rem)] lg:border lg:border-border-subtle lg:rounded-xl lg:bg-surface',
          sidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0',
        )}
      >
        <div className="flex items-center justify-between px-4 py-4 lg:hidden">
          <div className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-accent-600" />
            <p className="text-section font-semibold text-text-primary">Collabix AI</p>
          </div>
          <button
            type="button"
            onClick={() => setSidebarOpen(false)}
            aria-label="Close AI navigation"
            className="flex h-8 w-8 items-center justify-center rounded-lg text-text-tertiary hover:bg-surface-2 hover:text-text-primary transition-colors"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        <div className="p-3 hidden lg:block">
          <div className="flex items-center gap-2 px-2 py-3">
            <Sparkles className="h-5 w-5 text-accent-600 dark:text-accent-400" />
            <p className="text-section font-semibold text-text-primary">Collabix AI</p>
          </div>
        </div>

        <nav aria-label="AI sections" className="px-2 pb-4">
          {aiNavItems.map((item) => {
            const Icon = item.icon;
            const active = isActive(item.path);
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => { navigate(item.path); setSidebarOpen(false); }}
                className={cn(
                  'flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-body transition-colors text-left',
                  active
                    ? 'bg-accent-600/10 text-accent-700 dark:bg-accent-100/15 dark:text-accent-200 font-medium'
                    : 'text-text-secondary hover:bg-surface-2 hover:text-text-primary',
                )}
              >
                <Icon className={cn('h-4 w-4 shrink-0', active && 'text-accent-600 dark:text-accent-300')} />
                <span className="flex-1">{item.label}</span>
              </button>
            );
          })}
        </nav>
      </div>

      {/* Main content area */}
      <div className="flex-1 min-w-0 flex flex-col gap-6">
        <Outlet />
      </div>

      {/* Contextual right panel (prepared for future features) */}
      {rightPanelOpen && (
        <div className="hidden lg:block w-72 shrink-0 border border-border-subtle rounded-xl bg-surface overflow-y-auto h-[calc(100vh-7rem)] sticky top-0 p-4">
          <p className="text-caption font-medium text-text-tertiary">Context Panel</p>
          <p className="text-body text-text-secondary mt-2">
            AI context and suggestions will appear here.
          </p>
        </div>
      )}
    </div>
  );
}

import { BookMarked, FileText, ScrollText, Heart, Search, Sparkles } from 'lucide-react';
import { AIEmptyState } from '../AIEmptyState';

interface HistoryEmptyStateProps {
  variant: 'no-history' | 'no-reports' | 'no-summaries' | 'no-favorites' | 'no-results' | 'no-category';
  searchQuery?: string;
  onClearSearch?: () => void;
  onStartAction?: () => void;
}

export function HistoryEmptyState({ variant, searchQuery, onClearSearch, onStartAction }: HistoryEmptyStateProps) {
  if (variant === 'no-results') {
    return (
      <AIEmptyState
        icon={<Search />}
        title="No results found"
        description={searchQuery ? `No history items matching "${searchQuery}". Try a different search or adjust your filters.` : 'No items match your current filters.'}
        actionLabel="Clear Search"
        onAction={onClearSearch}
      />
    );
  }

  if (variant === 'no-favorites') {
    return (
      <AIEmptyState
        icon={<Heart />}
        title="No favorites yet"
        description="Save your most important conversations, reports and summaries as favorites. Click the heart icon on any history item to add it here."
      />
    );
  }

  if (variant === 'no-reports') {
    return (
      <AIEmptyState
        icon={<FileText />}
        title="No reports generated"
        description="Reports you generate with Collabix AI will appear here. Try generating an executive report or weekly summary."
        actionLabel="Generate a Report"
        onAction={onStartAction}
      />
    );
  }

  if (variant === 'no-summaries') {
    return (
      <AIEmptyState
        icon={<ScrollText />}
        title="No summaries yet"
        description="Summaries created by Collabix AI will appear here. Try summarizing a document or generating a handover summary."
        actionLabel="Create a Summary"
        onAction={onStartAction}
      />
    );
  }

  if (variant === 'no-category') {
    return (
      <AIEmptyState
        icon={<BookMarked />}
        title="No items in this category"
        description="There are no history items matching the selected category. Try a different filter."
      />
    );
  }

  return (
    <AIEmptyState
      icon={<BookMarked />}
      title="No AI history yet"
      description="Your AI activity timeline will appear here. Generate a report or summary with Collabix AI to populate your history."
      actionLabel="Generate a Report"
      onAction={onStartAction}
    />
  );
}

import { useState, useMemo } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Clock, Star, RefreshCw } from 'lucide-react';
import { HistoryHeader } from './HistoryHeader';
import { HistorySearch } from './HistorySearch';
import { HistoryFilters } from './HistoryFilters';
import { HistoryTimeline } from './HistoryTimeline';
import { HistoryDetailDrawer } from './HistoryDetailDrawer';
import { HistoryEmptyState } from './HistoryEmptyState';
import { HistoryLoading } from './HistoryLoading';
import { HistoryErrorCard } from './HistoryErrorCard';
import { type HistoryItem, type ActivityCategory } from './HistoryTypes';
import { useAIReportHistory } from '../../../services/reporting-ai-hooks';
import { useDepartmentList } from '../../../services/department-hooks';
import { useWorkspaceDetail } from '../../../services/workspace-hooks';
import type { ReportingResponse } from '../../../services/reporting-ai-service';

function mapReportToHistoryItem(report: ReportingResponse, workspaceName: string, departmentName: string): HistoryItem {
  const date = report.generationDate ? new Date(report.generationDate) : new Date();
  const now = new Date();
  const diffDays = Math.floor((now.getTime() - date.getTime()) / (1000 * 60 * 60 * 24));
  let label = 'Today';
  if (diffDays === 1) label = 'Yesterday';
  else if (diffDays <= 7) label = `${diffDays} days ago`;
  else if (diffDays <= 30) label = 'Last week';
  else label = 'Last month';

  return {
    id: report.reportId,
    type: 'executive-summary',
    title: report.title,
    description: report.executiveSummary?.slice(0, 120) ?? 'Executive report',
    category: 'reports',
    workspace: workspaceName,
    department: departmentName,
    date: label,
    time: date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    favorite: false,
    status: report.approvalStatus === 'APPROVED' ? 'completed' : 'draft',
  };
}

export function HistoryPage({
  workspaceId,
}: {
  workspaceId?: string;
}) {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const wsId = workspaceId || searchParams.get('ws') || '';
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<ActivityCategory | 'all'>('all');
  const [timeFilter, setTimeFilter] = useState('all-time');
  const [selectedItem, setSelectedItem] = useState<HistoryItem | null>(null);
  const [favorites, setFavorites] = useState<Set<string>>(new Set());
  const [error, setError] = useState<string | null>(null);
  const [searches, setSearches] = useState<string[]>([]);

  const { data: reportHistory, isLoading, isError } = useAIReportHistory(wsId);
  const { data: workspace } = useWorkspaceDetail(wsId || undefined);
  const { data: departments } = useDepartmentList(wsId || undefined);

  const deptNameById = useMemo(() => {
    const map: Record<string, string> = {};
    for (const d of departments ?? []) map[d.id] = d.name;
    return map;
  }, [departments]);

  const allItems = useMemo(() => {
    const items: HistoryItem[] = [];
    if (reportHistory?.content) {
      items.push(...reportHistory.content.map((report) => mapReportToHistoryItem(report, workspace?.name ?? 'Workspace', deptNameById[report.departmentId] ?? 'Department')));
    }
    return items;
  }, [reportHistory, workspace, deptNameById]);

  const items = useMemo(() => {
    let list = [...allItems];

    if (categoryFilter === 'favorites') {
      list = list.filter((i) => favorites.has(i.id));
    } else if (categoryFilter !== 'all') {
      list = list.filter((i) => i.category === categoryFilter);
    }

    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      list = list.filter(
        (i) =>
          i.title.toLowerCase().includes(q) ||
          i.description.toLowerCase().includes(q) ||
          i.workspace.toLowerCase().includes(q),
      );
    }

    return list;
  }, [allItems, categoryFilter, searchQuery, favorites]);

  const grouped = useMemo(() => {
    const groups: Record<string, HistoryItem[]> = {};
    const dateOrder = ['Today', 'Yesterday', '3 days ago', '4 days ago', '5 days ago', '6 days ago', 'Last week', 'Last month'];

    for (const item of items) {
      if (!groups[item.date]) groups[item.date] = [];
      groups[item.date].push(item);
    }

    return dateOrder.filter((d) => groups[d]).map((d) => ({ label: d, items: groups[d] }));
  }, [items]);

  function handleToggleFavorite(id: string) {
    setFavorites((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  function handleSearch(query: string) {
    setSearchQuery(query);
    if (query.trim() && !searches.includes(query.trim())) {
      setSearches((prev) => [query.trim(), ...prev].slice(0, 5));
    }
  }

  const favoriteItems = useMemo(() => allItems.filter((i) => favorites.has(i.id)), [allItems, favorites]);

  if (isLoading) return <HistoryLoading />;

  if (isError || error) {
    return (
      <div className="flex flex-col gap-6">
        <HistoryHeader />
        <HistoryErrorCard message={error ?? 'Failed to load history'} onRetry={() => setError(null)} onDismiss={() => setError(null)} />
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 animate-fade-in">
      <HistoryHeader />

      <HistorySearch
        query={searchQuery}
        onQueryChange={handleSearch}
        onClearSearch={() => setSearchQuery('')}
        recentSearches={searches}
      />

      <HistoryFilters
        categoryActive={categoryFilter}
        timeActive={timeFilter}
        onCategoryChange={setCategoryFilter}
        onTimeChange={setTimeFilter}
      />

      {categoryFilter === 'favorites' && favoriteItems.length > 0 && (
        <section className="flex flex-col gap-4">
          <div className="flex items-center gap-2">
            <Star className="h-4 w-4 text-text-tertiary" />
            <h2 className="text-section font-semibold text-text-primary">Favorites</h2>
          </div>
          <HistoryTimeline
            groups={[{ label: 'Favorites', items: favoriteItems }]}
            onItemClick={setSelectedItem}
            onToggleFavorite={handleToggleFavorite}
            favorites={favorites}
          />
        </section>
      )}

      {(categoryFilter !== 'favorites' || !favoriteItems.length) && (
        <>
          {grouped.length === 0 ? (
            <HistoryEmptyState
              variant={searchQuery ? 'no-results' : categoryFilter !== 'all' ? 'no-category' : 'no-history'}
              searchQuery={searchQuery}
              onClearSearch={() => setSearchQuery('')}
              onStartAction={() => navigate('/app/ai/reports')}
            />
          ) : (
            <div className="flex flex-col gap-4">
              {searchQuery && (
                <div className="flex items-center gap-2">
                  <Clock className="h-4 w-4 text-text-tertiary" />
                  <p className="text-caption text-text-secondary">
                    {items.length} result{items.length !== 1 ? 's' : ''} for &ldquo;{searchQuery}&rdquo;
                  </p>
                </div>
              )}
              <HistoryTimeline
                groups={grouped}
                onItemClick={setSelectedItem}
                onToggleFavorite={handleToggleFavorite}
                favorites={favorites}
              />
            </div>
          )}
        </>
      )}

      {selectedItem && (
        <HistoryDetailDrawer
          item={selectedItem}
          isFavorite={favorites.has(selectedItem.id)}
          onClose={() => setSelectedItem(null)}
          onToggleFavorite={() => handleToggleFavorite(selectedItem.id)}
          onReopen={() => navigate(`/app/ai/report/${wsId}/${selectedItem.id}`)}
          onCopy={() => navigator.clipboard.writeText(selectedItem.description)}
        />
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Wifi, WifiOff, RefreshCw, Clock } from 'lucide-react';
