import { useId } from 'react';
import { cn } from '../../lib/cn';

export interface ChartData {
  id?: string;
  label: string;
  value: number;
  color?: string;
  percentage?: number;
}

export interface BarChartProps {
  data: { label: string; value: number }[];
  height?: number;
  tone?: 'accent' | 'success' | 'warning' | 'danger' | 'info';
  className?: string;
}

const toneFill: Record<string, string> = {
  accent: 'rgb(var(--accent-500))',
  success: 'rgb(var(--success-500))',
  warning: 'rgb(var(--warning-500))',
  danger: 'rgb(var(--danger-500))',
  info: 'rgb(var(--info-500))',
};

export function BarChart({ data, height = 200, tone = 'accent', className }: BarChartProps) {
  const max = Math.max(...data.map((d) => d.value), 1);
  const barWidth = 100 / data.length;
  return (
    <div className={cn('w-full', className)}>
      <svg role="img" aria-label={`Bar chart showing ${data.map(d => `${d.label}: ${d.value}`).join(', ')}`} viewBox={`0 0 100 ${height / 2}`} preserveAspectRatio="none" className="w-full" style={{ height }}>
        {data.map((d, i) => {
          const h = (d.value / max) * (height / 2 - 16);
          const x = i * barWidth + barWidth * 0.2;
          const w = barWidth * 0.6;
          return (
            <rect
              key={i}
              x={x}
              y={height / 2 - h - 12}
              width={w}
              height={Math.max(0, h)}
              fill={toneFill[tone]}
              rx={0.5}
              opacity={0.9}
            >
              <animate attributeName="height" from="0" to={Math.max(0, h)} dur="0.5s" fill="freeze" />
              <animate attributeName="y" from={height / 2 - 12} to={height / 2 - h - 12} dur="0.5s" fill="freeze" />
            </rect>
          );
        })}
      </svg>
      <div className="mt-2 flex justify-between">
        {data.map((d, i) => (
          <span key={i} className="text-2xs text-text-tertiary truncate" style={{ width: `${barWidth}%` }}>
            {d.label}
          </span>
        ))}
      </div>
    </div>
  );
}

export interface LineChartProps {
  data: { label: string; value: number }[];
  height?: number;
  tone?: 'accent' | 'success' | 'warning' | 'danger' | 'info';
  className?: string;
}

export function LineChart({ data, height = 200, tone = 'accent', className }: LineChartProps) {
  const gradId = useId();
  const max = Math.max(...data.map((d) => d.value), 1);
  const min = Math.min(...data.map((d) => d.value), 0);
  const range = max - min || 1;
  const w = 100;
  const h = height / 2;
  const pad = 8;
  const stepX = data.length > 1 ? (w - pad * 2) / (data.length - 1) : 0;

  const points = data.map((d, i) => {
    const x = pad + i * stepX;
    const y = h - pad - ((d.value - min) / range) * (h - pad * 2);
    return [x, y] as const;
  });

  const path = points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p[0]} ${p[1]}`).join(' ');
  const areaPath = `${path} L ${points[points.length - 1]?.[0] ?? pad} ${h - pad} L ${points[0]?.[0] ?? pad} ${h - pad} Z`;

  return (
    <div className={cn('w-full', className)}>
      <svg role="img" aria-label={`Line chart showing ${data.map(d => `${d.label}: ${d.value}`).join(', ')}`} viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" className="w-full" style={{ height }}>
        <defs>
          <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={toneFill[tone]} stopOpacity="0.18" />
            <stop offset="100%" stopColor={toneFill[tone]} stopOpacity="0" />
          </linearGradient>
        </defs>
        <path d={areaPath} fill={`url(#${gradId})`} />
        <path d={path} fill="none" stroke={toneFill[tone]} strokeWidth={0.6} strokeLinecap="round" strokeLinejoin="round">
          <animate attributeName="stroke-dasharray" from="0 300" to="300 0" dur="0.8s" fill="freeze" />
        </path>
        {points.map((p, i) => (
          <circle key={i} cx={p[0]} cy={p[1]} r={0.8} fill={toneFill[tone]} />
        ))}
      </svg>
      <div className="mt-2 flex justify-between">
        {data.map((d, i) => (
          <span key={i} className="text-2xs text-text-tertiary">
            {d.label}
          </span>
        ))}
      </div>
    </div>
  );
}

export interface AreaChartProps extends LineChartProps {}

export function AreaChart(props: AreaChartProps) {
  return <LineChart {...props} />;
}

export interface PieChartProps {
  data: { label: string; value: number; tone?: 'accent' | 'success' | 'warning' | 'danger' | 'info' | 'neutral' }[];
  size?: number;
  className?: string;
}

const pieColors: Record<string, string> = {
  accent: 'rgb(var(--accent-500))',
  success: 'rgb(var(--success-500))',
  warning: 'rgb(var(--warning-500))',
  danger: 'rgb(var(--danger-500))',
  info: 'rgb(var(--info-500))',
  neutral: 'rgb(var(--border-strong))',
};

export function PieChart({ data, size = 160, className }: PieChartProps) {
  const total = data.reduce((s, d) => s + d.value, 0) || 1;
  const radius = 40;
  const cx = 50;
  const cy = 50;
  let cumulative = 0;

  const segments = data.map((d) => {
    const startAngle = (cumulative / total) * 2 * Math.PI - Math.PI / 2;
    cumulative += d.value;
    const endAngle = (cumulative / total) * 2 * Math.PI - Math.PI / 2;
    const x1 = cx + radius * Math.cos(startAngle);
    const y1 = cy + radius * Math.sin(startAngle);
    const x2 = cx + radius * Math.cos(endAngle);
    const y2 = cy + radius * Math.sin(endAngle);
    const largeArc = endAngle - startAngle > Math.PI ? 1 : 0;
    return {
      path: `M ${cx} ${cy} L ${x1} ${y1} A ${radius} ${radius} 0 ${largeArc} 1 ${x2} ${y2} Z`,
      color: pieColors[d.tone ?? 'neutral'],
      label: d.label,
      pct: Math.round((d.value / total) * 100),
    };
  });

  return (
    <div className={cn('flex items-center gap-6', className)}>
      <svg role="img" aria-label={`Pie chart showing ${data.map(d => `${d.label}: ${Math.round((d.value / total) * 100)}%`).join(', ')}`} viewBox="0 0 100 100" style={{ width: size, height: size }} className="shrink-0">
        {segments.map((s, i) => (
          <path key={i} d={s.path} fill={s.color} opacity={0.9} stroke="rgb(var(--bg-elevated))" strokeWidth={0.5} />
        ))}
      </svg>
      <div className="flex flex-col gap-2 min-w-0">
        {segments.map((s, i) => (
          <div key={i} className="flex items-center gap-2">
            <span className="h-2.5 w-2.5 rounded-sm shrink-0" style={{ backgroundColor: s.color }} />
            <span className="text-caption text-text-secondary truncate">{s.label}</span>
            <span className="text-caption font-medium text-text-tertiary ml-auto">{s.pct}%</span>
          </div>
        ))}
      </div>
    </div>
  );
}

export interface ActivityChartProps {
  data: { date: string; value: number }[];
  height?: number;
  className?: string;
}

export function ActivityChart({ data, height = 120, className }: ActivityChartProps) {
  const max = Math.max(...data.map((d) => d.value), 1);
  const cellSize = 12;
  const gap = 3;
  const weeks = Math.ceil(data.length / 7);

  return (
    <div className={cn('w-full overflow-x-auto', className)}>
      <svg
        width={weeks * (cellSize + gap)}
        height={7 * (cellSize + gap)}
        className="block"
      >
        {data.map((d, i) => {
          const col = Math.floor(i / 7);
          const row = i % 7;
          const intensity = d.value / max;
          const opacity = d.value === 0 ? 0.08 : 0.2 + intensity * 0.8;
          return (
            <rect
              key={i}
              x={col * (cellSize + gap)}
              y={row * (cellSize + gap)}
              width={cellSize}
              height={cellSize}
              rx={2}
              fill="rgb(var(--accent-500))"
              opacity={opacity}
            >
              <title>{`${d.date}: ${d.value}`}</title>
            </rect>
          );
        })}
      </svg>
    </div>
  );
}

import { createContext, useCallback, useContext, useState, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { CheckCircle2, AlertCircle, Info, XCircle, X } from 'lucide-react';
import { cn } from '../../lib/cn';

type ToastTone = 'success' | 'warning' | 'danger' | 'info';

interface Toast {
  id: number;
  title: string;
  description?: string;
  tone?: ToastTone;
}

interface ToastContextValue {
  toast: (t: Omit<Toast, 'id'>) => void;
}

const ToastContext = createContext<ToastContextValue | undefined>(undefined);

const toneConfig: Record<ToastTone, { icon: ReactNode; color: string }> = {
  success: { icon: <CheckCircle2 className="h-5 w-5" />, color: 'text-success-500' },
  warning: { icon: <AlertCircle className="h-5 w-5" />, color: 'text-warning-500' },
  danger: { icon: <XCircle className="h-5 w-5" />, color: 'text-danger-500' },
  info: { icon: <Info className="h-5 w-5" />, color: 'text-info-500' },
};

export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const toast = useCallback((t: Omit<Toast, 'id'>) => {
    const id = Date.now() + Math.random();
    setToasts((prev) => [...prev, { ...t, tone: t.tone ?? 'info', id }]);
    setTimeout(() => {
      setToasts((prev) => prev.filter((x) => x.id !== id));
    }, 4000);
  }, []);

  const dismiss = (id: number) => setToasts((prev) => prev.filter((x) => x.id !== id));

  return (
    <ToastContext.Provider value={{ toast }}>
      {children}
      {createPortal(
        <div className="fixed bottom-4 right-4 z-[60] flex flex-col gap-2 w-[360px] max-w-[calc(100vw-2rem)]">
          {toasts.map((t) => {
            const cfg = toneConfig[t.tone ?? 'info'];
            return (
              <div
                key={t.id}
                className="flex items-start gap-3 rounded-lg border border-border-subtle bg-elevated p-4 shadow-cx-lg animate-slide-in-right"
                role="alert"
              >
                <span className={cn('shrink-0 mt-0.5', cfg.color)}>{cfg.icon}</span>
                <div className="min-w-0 flex-1">
                  <p className="text-body font-medium text-text-primary">{t.title}</p>
                  {t.description && <p className="mt-0.5 text-caption text-text-tertiary">{t.description}</p>}
                </div>
                <button
                  type="button"
                  onClick={() => dismiss(t.id)}
                  aria-label="Dismiss"
                  className="shrink-0 flex h-6 w-6 items-center justify-center rounded text-text-tertiary hover:bg-surface-2 hover:text-text-primary transition-colors"
                >
                  <X className="h-3.5 w-3.5" />
                </button>
              </div>
            );
          })}
        </div>,
        document.body,
      )}
    </ToastContext.Provider>
  );
}

export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error('useToast must be used within a ToastProvider');
  return ctx;
}

import { useState, useCallback, useMemo } from 'react';
import type { Pageable, SortField, SortDirection, PageMetadata } from '../types/api';
import { DEFAULT_PAGEABLE } from '../types/api';

export interface PaginationConfig {
  initialPage?: number;
  initialSize?: number;
  initialSort?: SortField[];
}

export function usePagination(config: PaginationConfig = {}) {
  const [page, setPage] = useState(config.initialPage ?? 0);
  const [size, setSize] = useState(config.initialSize ?? 20);
  const [sortFields, setSortFields] = useState<SortField[]>(config.initialSort ?? []);
  const [metadata, setMetadata] = useState<PageMetadata | null>(null);

  const pageable: Pageable = useMemo(
    () => ({ page, size, sort: sortFields.map((s) => `${s.field},${s.direction}`) }),
    [page, size, sortFields],
  );

  const resetPage = useCallback(() => setPage(0), []);

  const nextPage = useCallback(() => {
    if (metadata && !metadata.last) setPage((p) => p + 1);
  }, [metadata]);

  const prevPage = useCallback(() => {
    if (metadata && !metadata.first) setPage((p) => Math.max(0, p - 1));
  }, [metadata]);

  const goToPage = useCallback((p: number) => {
    setPage(Math.max(0, p));
  }, []);

  const changeSize = useCallback((newSize: number) => {
    setSize(newSize);
    setPage(0);
  }, []);

  const toggleSort = useCallback(
    (field: string) => {
      setSortFields((prev) => {
        const existing = prev.find((s) => s.field === field);
        if (!existing) return [{ field, direction: 'asc' as SortDirection }];
        if (existing.direction === 'asc') return [{ field, direction: 'desc' as SortDirection }];
        return [];
      });
      setPage(0);
    },
    [],
  );

  const setSort = useCallback((fields: SortField[]) => {
    setSortFields(fields);
    setPage(0);
  }, []);

  const syncMetadata = useCallback((meta: PageMetadata) => {
    setMetadata(meta);
  }, []);

  const from = metadata ? metadata.page * metadata.size + 1 : 0;
  const to = metadata ? Math.min((metadata.page + 1) * metadata.size, metadata.totalElements) : 0;

  return {
    page,
    size,
    pageable,
    sortFields,
    metadata,
    from,
    to,
    setPage: goToPage,
    nextPage,
    prevPage,
    resetPage,
    changeSize,
    toggleSort,
    setSort,
    syncMetadata,
  };
}

export type PaginationControls = ReturnType<typeof usePagination>;

import { createContext, useContext, useState, useCallback, useMemo, useEffect, type ReactNode } from 'react';
import { apiClient } from './api';
import { onAuthEvent, type AuthEvent } from './auth-events';
import { authService } from '../services/auth-service';
import type { LoginResponse, UserResponse, MemberType } from '../types';

/* ---------- JWT Decode (minimal, no library needed) ---------- */

function decodeJwt(token: string): Record<string, unknown> | null {
  try {
    const payload = token.split('.')[1];
    return JSON.parse(atob(payload));
  } catch {
    return null;
  }
}

function extractPermissions(token: string): string[] {
  const claims = decodeJwt(token);
  if (!claims) return [];
  const perms = claims['permissions'];
  return Array.isArray(perms) ? perms.map(String) : [];
}

/* ---------- Types ---------- */

export interface User {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  roles: string[];
  permissions: string[];
  memberType: MemberType;
  profilePicture?: string;
  departmentId?: string;
  departmentName?: string;
  teamId?: string;
  teamName?: string;
}

export interface AuthState {
  user: User | null;
  accessToken: string | null;
  refreshToken: string | null;
}

export interface LoginPayload {
  email: string;
  password: string;
  remember?: boolean;
}

export interface LoginResult {
  accessToken: string;
  refreshToken: string;
  user: User;
}

export interface AuthContextValue extends AuthState {
  isAuthenticated: boolean;
  isAuthLoading: boolean;
  isRefreshing: boolean;
  sessionExpired: boolean;
  lastAuthEvent: AuthEvent | null;
  signIn: (payload: LoginPayload) => Promise<LoginResult>;
  signOut: () => void;
  clearSessionExpiry: () => void;
}

const AuthContext = createContext<AuthContextValue | null>(null);

const AUTH_STORAGE_KEY = 'collabix_auth';

function mapUserResponse(r: UserResponse, token: string): User {
  return {
    id: r.id,
    email: r.email,
    firstName: r.firstName,
    lastName: r.lastName,
    roles: r.role ? [r.role] : [],
    permissions: extractPermissions(token),
    memberType: r.memberType,
    profilePicture: r.profilePicture,
    departmentId: r.departmentId,
    departmentName: r.departmentName,
    teamId: r.teamId,
    teamName: r.teamName,
  };
}

function loadAuth(): AuthState {
  try {
    const stored = localStorage.getItem(AUTH_STORAGE_KEY);
    if (stored) {
      const parsed = JSON.parse(stored) as AuthState;
      if (parsed.accessToken && parsed.user) {
        return parsed;
      }
    }
  } catch {
    // corrupted data
  }
  return { user: null, accessToken: null, refreshToken: null };
}

function persistAuth(state: AuthState) {
  if (state.accessToken && state.user) {
    localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(state));
  }
}

function clearAuth() {
  localStorage.removeItem(AUTH_STORAGE_KEY);
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AuthState>(loadAuth);
  const [sessionExpired, setSessionExpired] = useState(false);
  const [lastAuthEvent, setLastAuthEvent] = useState<AuthEvent | null>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Multi-tab synchronization
  useEffect(() => {
    function handleStorage(e: StorageEvent) {
      if (e.key === AUTH_STORAGE_KEY) {
        if (e.newValue) {
          try {
            const parsed = JSON.parse(e.newValue) as AuthState;
            if (parsed.accessToken && parsed.user) {
              setState(parsed);
              setSessionExpired(false);
            } else {
              setState({ user: null, accessToken: null, refreshToken: null });
            }
          } catch {
            setState({ user: null, accessToken: null, refreshToken: null });
          }
        } else {
          setState({ user: null, accessToken: null, refreshToken: null });
        }
      }
    }
    window.addEventListener('storage', handleStorage);
    return () => window.removeEventListener('storage', handleStorage);
  }, []);

  // Global auth event subscription
  useEffect(() => {
    const unsubscribe = onAuthEvent((event) => {
      setLastAuthEvent(event);
      if (event.type === 'session-expired') {
        clearAuth();
        setState({ user: null, accessToken: null, refreshToken: null });
        setSessionExpired(true);
      }
      if (event.type === 'token-refreshed') {
        const fresh = loadAuth();
        if (fresh.accessToken && fresh.user) {
          setState(fresh);
        }
      }
    });
    return unsubscribe;
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => setIsAuthLoading(false), 300);
    return () => clearTimeout(timer);
  }, []);

  const signIn = useCallback(
    async (payload: LoginPayload): Promise<LoginResult> => {
      setIsRefreshing(true);
      try {
        const loginRes = await authService.login({
          email: payload.email,
          password: payload.password,
        });
        const user = mapUserResponse(loginRes.user, loginRes.accessToken);
        const result: LoginResult = {
          accessToken: loginRes.accessToken,
          refreshToken: loginRes.refreshToken,
          user,
        };
        const newState: AuthState = {
          user,
          accessToken: loginRes.accessToken,
          refreshToken: loginRes.refreshToken,
        };
        persistAuth(newState);
        setState(newState);
        setSessionExpired(false);
        return result;
      } finally {
        setIsRefreshing(false);
      }
    },
    [],
  );

  const signOut = useCallback(async () => {
    const currentRefreshToken = state.refreshToken;
    try {
      if (currentRefreshToken) {
        await authService.logout({ refreshToken: currentRefreshToken });
      }
    } catch {
      // Logout API failure is non-blocking
    }
    clearAuth();
    setState({ user: null, accessToken: null, refreshToken: null });
    setSessionExpired(false);
  }, [state.refreshToken]);

  const clearSessionExpiry = useCallback(() => {
    setSessionExpired(false);
    setLastAuthEvent(null);
  }, []);

  const value = useMemo<AuthContextValue>(
    () => ({
      ...state,
      isAuthenticated: !!state.user && !!state.accessToken,
      isAuthLoading,
      isRefreshing,
      sessionExpired,
      lastAuthEvent,
      signIn,
      signOut,
      clearSessionExpiry,
    }),
    [state, isAuthLoading, isRefreshing, sessionExpired, lastAuthEvent, signIn, signOut, clearSessionExpiry],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return ctx;
}

/* ---------- Query Key Factory ---------- */

type Key = readonly unknown[];

export function createQueryKeys<T extends Record<string, (...args: any[]) => Key>>(domain: string, definitions: T): { all: Key; list: (filters?: Record<string, unknown>) => Key; details: T } {
  const all: Key = [domain];

  const list = (filters?: Record<string, unknown>): Key => {
    if (filters) return [domain, 'list', filters];
    return [domain, 'list'];
  };

  const details = {} as T;
  for (const key in definitions) {
    const fn = definitions[key];
    details[key] = ((...args: unknown[]) => [domain, key, ...fn(...args)]) as unknown as T[Extract<keyof T, string>];
  }

  return { all, list, details };
}

