  return (
    <div className="flex flex-col gap-8 animate-fade-in">
      <AIHeader onHistory={() => navigate('/app/ai/history')} />

      <AIHero
        greeting={`${getGreeting()}, ${user?.firstName ?? 'there'}.`}
