        </div>
      </AISection>

      <AISection title="AI Statistics" description="Your AI workspace at a glance">
        <div className="grid gap-4 grid-cols-2 sm:grid-cols-3 lg:grid-cols-6">
          {aiStats.map((stat) => (
            <AIStatCard key={stat.id} icon={stat.icon} label={stat.label} value={stat.value} description={stat.description} tone={stat.tone} />
          ))}
        </div>
      </AISection>

      <div className="grid gap-8 lg:grid-cols-3">
        <div className="lg:col-span-2">
          <AISection title="Recent AI Activities" description="Latest actions performed by Collabix AI">
            <Card>
              <CardBody>
                {recentActivities.length === 0 ? (
                  <p className="text-caption text-text-tertiary py-4 text-center">No activities yet</p>
                ) : (
                  <AIActivityCard items={recentActivities} />
                )}
              </CardBody>
            </Card>
          </AISection>
        </div>
        <div>
          <AISection title="Suggested Actions">
            <div className="flex flex-col gap-2">
              {suggestedActions.map((action) => (
                <AISuggestionCard key={action.id} icon={action.icon} title={action.title} onClick={() => navigate('/app/ai/analytics')} />
              ))}
            </div>
          </AISection>
        </div>
      </div>

      <AIReportPreview
        items={reportItems}
        onViewAll={() => navigate('/app/ai/reports')}
        onOpen={(id) => navigate(`/app/ai/report/${workspaceId}/${id}`)}
      />
    </div>
  );
}

import { AlertTriangle, AlertCircle, Info, ShieldAlert } from 'lucide-react';
import { cn } from '../../lib/cn';

export type AuthErrorTone = 'error' | 'warning' | 'info';

const toneConfig: Record<AuthErrorTone, { container: string; text: string; icon: typeof AlertCircle }> = {
  error: {
    container: 'border-danger-100 bg-danger-50',
    text: 'text-danger-700',
    icon: AlertCircle,
  },
  warning: {
    container: 'border-warning-100 bg-warning-50',
    text: 'text-warning-700',
    icon: AlertTriangle,
  },
  info: {
    container: 'border-info-100 bg-info-50',
    text: 'text-info-700',
    icon: Info,
  },
};

const iconColor: Record<AuthErrorTone, string> = {
  error: 'text-danger-500',
  warning: 'text-warning-500',
  info: 'text-info-500',
};

export interface AuthErrorAlertProps {
  tone: AuthErrorTone;
  title?: string;
  message: string;
  className?: string;
}

export function AuthErrorAlert({ tone, title, message, className }: AuthErrorAlertProps) {
  const config = toneConfig[tone];
  const Icon = config.icon;

  return (
    <div
      role="alert"
      className={cn(
        'flex items-start gap-3 rounded-lg border px-4 py-3.5',
        config.container,
        className,
      )}
    >
      <Icon className={cn('h-5 w-5 shrink-0 mt-0.5', iconColor[tone])} />
      <div className="min-w-0">
        {title && (
          <p className={cn('text-caption font-semibold mb-0.5', config.text)}>
            {title}
          </p>
        )}
        <p className={cn('text-caption leading-relaxed', config.text)}>
          {message}
        </p>
      </div>
    </div>
  );
}

export interface AuthErrorListProps {
  errors: { title?: string; message: string; tone?: AuthErrorTone }[];
}

export function AuthErrorList({ errors }: AuthErrorListProps) {
  if (errors.length === 0) return null;

  return (
    <div className="flex flex-col gap-2">
      {errors.map((err, i) => (
        <AuthErrorAlert
          key={i}
          tone={err.tone ?? 'error'}
          title={err.title}
          message={err.message}
        />
      ))}
    </div>
  );
}

import { useState, useRef, useEffect, useMemo } from 'react';
import { useParams, useSearchParams } from 'react-router-dom';
import { Send, Paperclip, Pin, MoreHorizontal, UserPlus, Hash, ArrowLeft, Loader2 } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Avatar } from '../../components/ui/Avatar';
import { IconButton } from '../../components/ui/IconButton';
import { EmptyState } from '../../components/ui/EmptyState';
import { cn } from '../../lib/cn';
import { useConversationDetail, useConversationMembers } from '../../services/conversation-hooks';
import { useMessages, useCreateMessage, useUpdateMessage, usePinnedMessages } from '../../services/message-hooks';
import { formatRelativeTime } from '../../lib/format';
import type { MessageResponse } from '../../types/communication';

export function ChatWindow() {
  const { conversationId } = useParams();
  const [searchParams] = useSearchParams();
  const wsId = searchParams.get('ws') ?? '';
  const [newMessage, setNewMessage] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const { data: conversation, isLoading: convLoading } = useConversationDetail(wsId, conversationId);
  const { data: members } = useConversationMembers(wsId, conversationId ?? '');
  const { data: pinnedData } = usePinnedMessages(wsId, conversationId ?? '');
  const { data: messagesPages, isLoading: msgsLoading, fetchNextPage, hasNextPage } = useMessages(wsId, conversationId ?? '');
  const createMessage = useCreateMessage(wsId, conversationId ?? '');
  const updateMessage = useUpdateMessage(wsId, conversationId ?? '');

  const handleTogglePin = async (message: MessageResponse) => {
    if (!conversationId) return;
    try {
      await updateMessage.mutateAsync({ msgId: message.id, data: { isPinned: !message.isPinned } });
    } catch {
      // handled by mutation
    }
  };

  const messages = useMemo(() => {
    if (!messagesPages?.pages) return [];
    return messagesPages.pages.flatMap((p) => p.content);
  }, [messagesPages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages.length]);

  const handleSend = async () => {
    if (!newMessage.trim() || !conversationId) return;
    try {
      await createMessage.mutateAsync({ content: newMessage.trim() });
      setNewMessage('');
      inputRef.current?.focus();
    } catch {
      // handled by mutation
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  if (convLoading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="h-6 w-6 animate-spin text-text-tertiary" />
      </div>
    );
  }

  if (!conversation) {
    return (
      <EmptyState
        icon={<Hash className="h-8 w-8" />}
        title="Select a conversation"
        description="Choose a channel or direct message from the list."
      />
    );
  }

  return (
    <div className="flex h-full flex-col rounded-xl border border-border-subtle bg-elevated">
      <div className="flex items-center justify-between border-b border-border-subtle px-4 py-3">
        <div className="flex items-center gap-3">
          <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-accent-50 text-accent-600 dark:bg-accent-100 dark:text-accent-300">
            {conversation.isPrivate ? <UserPlus className="h-4 w-4" /> : <Hash className="h-4 w-4" />}
          </div>
          <div>
            <p className="text-body font-semibold text-text-primary">{conversation.name}</p>
            <p className="text-caption text-text-tertiary">{conversation.memberCount} members</p>
          </div>
        </div>
        <div className="flex items-center gap-1">
          {pinnedData && pinnedData.length > 0 && (
            <IconButton label={`${pinnedData.length} pinned messages`}>
              <Pin className="h-4 w-4" />
            </IconButton>
          )}
          <IconButton label="More options">
            <MoreHorizontal className="h-4 w-4" />
          </IconButton>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-3">
        {hasNextPage && (
          <div className="flex justify-center">
            <Button variant="ghost" size="sm" onClick={() => fetchNextPage()}>
              Load older messages
            </Button>
          </div>
        )}

        {msgsLoading && messages.length === 0 ? (
          <div className="flex items-center justify-center py-10">
            <Loader2 className="h-5 w-5 animate-spin text-text-tertiary" />
          </div>
        ) : messages.length === 0 ? (
          <div className="flex items-center justify-center py-10">
            <p className="text-caption text-text-tertiary">No messages yet. Start the conversation!</p>
          </div>
        ) : (
          messages.map((msg) => (
            <MessageBubble key={msg.id} message={msg} onTogglePin={() => handleTogglePin(msg)} />
          ))
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="border-t border-border-subtle px-4 py-3">
        <div className="flex items-center gap-2">
          <IconButton label="Attach file">
            <Paperclip className="h-4 w-4" />
          </IconButton>
          <div className="flex-1">
            <Input
              ref={inputRef}
              placeholder={`Message #${conversation.name}`}
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyDown={handleKeyDown}
            />
          </div>
          <Button
            variant="primary"
            size="sm"
            onClick={handleSend}
            disabled={!newMessage.trim() || createMessage.isPending}
          >
            {createMessage.isPending ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Send className="h-4 w-4" />
            )}
          </Button>
        </div>
      </div>
    </div>
  );
}

function MessageBubble({ message, onTogglePin }: { message: MessageResponse; onTogglePin?: () => void }) {
  const isDeleted = message.status === 'DELETED';

  return (
    <div className={cn('flex items-start gap-3 group', isDeleted && 'opacity-50')}>
      <Avatar
        src={message.senderProfilePicture}
        name={`${message.senderFirstName} ${message.senderLastName}`}
        size="sm"
      />
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <span className="text-body font-semibold text-text-primary">
            {message.senderFirstName} {message.senderLastName}
          </span>
          <span className="text-2xs text-text-tertiary">
            {formatRelativeTime(message.createdAt)}
          </span>
          {message.status === 'EDITED' && (
            <span className="text-2xs text-text-tertiary">(edited)</span>
          )}
          {message.isPinned && (
            <Pin className="h-3 w-3 text-amber-500" />
          )}
          {onTogglePin && !isDeleted && (
            <button
              type="button"
              onClick={onTogglePin}
              title={message.isPinned ? 'Unpin message' : 'Pin message'}
              className="ml-auto text-text-tertiary opacity-0 transition-opacity group-hover:opacity-100 hover:text-amber-500"
            >
              <Pin className="h-3.5 w-3.5" />
            </button>
          )}
        </div>
        <p className={cn(
          'text-body text-text-primary mt-0.5',
          isDeleted && 'italic text-text-tertiary',
        )}>
          {message.content}
        </p>
        {message.fileUrl && (
          <div className="mt-2 rounded-lg border border-border-subtle bg-surface-2 p-3">
            <p className="text-caption font-medium text-text-primary">{message.fileName}</p>
            {message.mimeType?.startsWith('image/') && (
              <img src={message.fileUrl} alt={message.fileName ?? ''} className="mt-2 max-h-48 rounded object-contain" />
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useLocation, Outlet, useNavigate, useSearchParams } from 'react-router-dom';
import { MessageSquare, Hash, Users, Bell, Search, FileText, Plus } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { cn } from '../../lib/cn';
import { CreateChannelModal } from './modals/CreateChannelModal';

const tabs = [
  { id: 'conversations', label: 'Channels', icon: Hash },
  { id: 'direct-messages', label: 'Direct Messages', icon: MessageSquare },
  { id: 'announcements', label: 'Announcements', icon: Bell },
  { id: 'search', label: 'Search', icon: Search },
  { id: 'files', label: 'Shared Files', icon: FileText },
];

export function CommunicationLayout() {
  const [searchParams] = useSearchParams();
  const wsId = searchParams.get('ws') ?? '';
  const navigate = useNavigate();
  const location = useLocation();
  const [createOpen, setCreateOpen] = useState(false);

  const segments = location.pathname.split('/');
  const commIdx = segments.indexOf('communication');
  const activeTab = commIdx >= 0 ? (segments[commIdx + 1] ?? '') : '';

  const handleTabChange = (tabId: string) => {
    navigate(`/app/communication/${tabId}${wsId ? `?ws=${wsId}` : ''}`);
  };

  return (
    <div className="flex h-full flex-col gap-4">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-page font-semibold text-text-primary">Communication</h1>
          <p className="text-caption text-text-tertiary mt-0.5">
            Team conversations and announcements
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="primary" onClick={() => setCreateOpen(true)}>
            <Plus className="h-4 w-4" />
            Create Channel
          </Button>
        </div>
      </div>

      <div className="flex gap-3 border-b border-border-subtle pb-2">
        {tabs.map((tab) => {
          const Icon = tab.icon;
          const isActive = activeTab === tab.id;
          return (
            <button
              key={tab.id}
              type="button"
              onClick={() => handleTabChange(tab.id)}
              className={cn(
                'flex items-center gap-2 rounded-lg px-3 py-2 text-body font-medium transition-colors',
                isActive
                  ? 'bg-accent-50 text-accent-700 dark:bg-accent-100 dark:text-accent-200'
                  : 'text-text-tertiary hover:text-text-primary hover:bg-surface-2',
              )}
            >
              <Icon className="h-4 w-4" />
              {tab.label}
            </button>
          );
        })}
      </div>

      <div className="flex-1">
        <Outlet />
      </div>

      <CreateChannelModal open={createOpen} onClose={() => setCreateOpen(false)} />
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { Hash, Users, Lock, Plus, Search, MoreHorizontal } from 'lucide-react';
import { Card, CardBody } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { IconButton } from '../../components/ui/IconButton';
import { EmptyState } from '../../components/ui/EmptyState';
import { Tabs, type TabItem } from '../../components/ui/Tabs';
import { Dropdown } from '../../components/ui/Dropdown';
import { cn } from '../../lib/cn';
import { useConversationsList, useConversationsByType } from '../../services/conversation-hooks';
import { CreateChannelModal } from './modals/CreateChannelModal';
import type { ConversationResponse, ConversationType } from '../../types/communication';

const tabs: TabItem[] = [
  { id: 'all', label: 'All Channels' },
  { id: 'WORKSPACE', label: 'Workspace' },
  { id: 'DEPARTMENT', label: 'Department' },
  { id: 'TEAM', label: 'Team' },
];

export function ConversationList() {
  const [searchParams] = useSearchParams();
  const wsId = searchParams.get('ws') ?? '';
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('all');
  const [search, setSearch] = useState('');
  const [createOpen, setCreateOpen] = useState(false);

  const { data: allData } = useConversationsList(wsId);
  const { data: workspaceData } = useConversationsByType(wsId, 'WORKSPACE');
  const { data: deptData } = useConversationsByType(wsId, 'DEPARTMENT');
  const { data: teamData } = useConversationsByType(wsId, 'TEAM');

  const conversations = useMemo(() => {
    let items: ConversationResponse[] = [];
    switch (activeTab) {
      case 'all':
        items = allData?.content ?? [];
        break;
      case 'WORKSPACE':
        items = workspaceData?.content ?? [];
        break;
      case 'DEPARTMENT':
        items = deptData?.content ?? [];
        break;
      case 'TEAM':
        items = teamData?.content ?? [];
        break;
    }
    if (search) {
      items = items.filter((c) =>
        c.name.toLowerCase().includes(search.toLowerCase()),
      );
    }
    return items;
  }, [activeTab, allData, workspaceData, deptData, teamData, search]);

  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-center justify-between gap-4">
        <div className="flex-1 max-w-md">
          <Input
            placeholder="Search channels..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            leftIcon={<Search className="h-4 w-4" />}
          />
        </div>
        <Button variant="primary" onClick={() => setCreateOpen(true)}>
          <Plus className="h-4 w-4" />
          New Channel
        </Button>
      </div>

      <Tabs items={tabs} active={activeTab} onChange={setActiveTab} />

      {conversations.length === 0 ? (
        <Card>
          <CardBody>
            <EmptyState
              icon={<Hash className="h-8 w-8" />}
              title="No channels found"
              description={search ? 'Try a different search term.' : 'Create a new channel to get started.'}
              action={
                <Button variant="primary" onClick={() => setCreateOpen(true)}>
                  <Plus className="h-4 w-4" />
                  Create Channel
                </Button>
              }
            />
          </CardBody>
        </Card>
      ) : (
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {conversations.map((conv) => (
            <button
              key={conv.id}
              type="button"
              onClick={() => navigate(`/app/communication/chat/${conv.id}?ws=${wsId}`)}
              className="flex flex-col gap-3 rounded-xl border border-border-subtle bg-elevated p-4 text-left hover:border-border-default hover:shadow-cx-sm transition-all"
            >
              <div className="flex items-start justify-between">
                <div className="flex items-center gap-2.5">
                  <span className="flex h-9 w-9 items-center justify-center rounded-lg bg-accent-50 text-accent-600 dark:bg-accent-100 dark:text-accent-300">
                    {conv.isPrivate ? <Lock className="h-4 w-4" /> : <Hash className="h-4 w-4" />}
                  </span>
                  <div>
                    <p className="text-body font-semibold text-text-primary">{conv.name}</p>
                    <p className="text-caption text-text-tertiary capitalize">{conv.type.toLowerCase()}</p>
                  </div>
                </div>
                <Dropdown
                  trigger={<IconButton label="Options"><MoreHorizontal className="h-4 w-4" /></IconButton>}
                  items={[
                    { label: 'Open Channel', onClick: () => navigate(`/app/communication/chat/${conv.id}?ws=${wsId}`) },
                  ]}
                />
              </div>
              {conv.lastMessagePreview && (
                <p className="text-caption text-text-tertiary line-clamp-2">{conv.lastMessagePreview}</p>
              )}
              <div className="flex items-center justify-between mt-auto">
                <div className="flex items-center gap-1.5 text-caption text-text-tertiary">
                  <Users className="h-3.5 w-3.5" />
                  {conv.memberCount}
                </div>
                {conv.unreadCount > 0 && (
                  <Badge tone="accent">{conv.unreadCount}</Badge>
                )}
              </div>
            </button>
          ))}
        </div>
      )}

      <CreateChannelModal open={createOpen} onClose={() => setCreateOpen(false)} />
    </div>
  );
}

import { useState } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { Search, Hash, MessageSquare, Loader2 } from 'lucide-react';
import { Card, CardBody } from '../../components/ui/Card';
import { Input } from '../../components/ui/Input';
import { EmptyState } from '../../components/ui/EmptyState';
import { useConversationsList } from '../../services/conversation-hooks';
import { useSearchMessages, useSearchWorkspaceMessages } from '../../services/message-hooks';
import { Avatar } from '../../components/ui/Avatar';
import { formatRelativeTime } from '../../lib/format';

export function MessageSearch() {
  const [searchParams] = useSearchParams();
  const wsId = searchParams.get('ws') ?? '';
  const navigate = useNavigate();
  const [query, setQuery] = useState('');
  const [selectedConvId, setSelectedConvId] = useState<string | undefined>();

  const { data: conversations } = useConversationsList(wsId);
  const convResults = useSearchMessages(wsId, selectedConvId ?? '', query);
  const wsResults = useSearchWorkspaceMessages(wsId, query);
  const results = selectedConvId ? convResults.data : wsResults.data;
  const isLoading = selectedConvId ? convResults.isLoading : wsResults.isLoading;

  const handleSearch = () => {
    if (!query.trim()) return;
  };

  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-start gap-4">
        <div className="flex-1 max-w-lg">
          <Input
            placeholder="Search messages..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
            leftIcon={<Search className="h-4 w-4" />}
          />
        </div>
        {conversations && conversations.content.length > 0 && (
          <div className="flex flex-wrap gap-2">
            <button
              type="button"
              onClick={() => setSelectedConvId(undefined)}
              className={`rounded-full px-3 py-1 text-2xs font-medium transition-colors ${
                !selectedConvId ? 'bg-accent-600 text-white' : 'bg-surface-2 text-text-tertiary hover:text-text-primary'
              }`}
            >
              All Channels
            </button>
            {conversations.content.slice(0, 8).map((conv) => (
              <button
                key={conv.id}
                type="button"
                onClick={() => setSelectedConvId(conv.id)}
                className={`rounded-full px-3 py-1 text-2xs font-medium transition-colors ${
                  selectedConvId === conv.id ? 'bg-accent-600 text-white' : 'bg-surface-2 text-text-tertiary hover:text-text-primary'
                }`}
              >
                {conv.name}
              </button>
            ))}
          </div>
        )}
      </div>

      <Card>
        <CardBody>
          {isLoading ? (
            <div className="flex items-center justify-center py-10">
              <Loader2 className="h-6 w-6 animate-spin text-text-tertiary" />
            </div>
          ) : !query ? (
            <EmptyState
              icon={<Search className="h-8 w-8" />}
              title="Search messages"
              description="Enter a search term and filter by channel to find messages."
            />
          ) : !results?.content || results.content.length === 0 ? (
            <EmptyState
              icon={<Search className="h-8 w-8" />}
              title="No results"
              description={`No messages found for "${query}".`}
            />
          ) : (
            <div className="flex flex-col gap-2">
              {results.content.map((msg) => (
                <button
                  key={msg.id}
                  type="button"
                  onClick={() => navigate(`/app/communication/chat/${msg.conversationId}?ws=${wsId}`)}
                  className="flex items-start gap-3 rounded-lg px-3 py-2.5 hover:bg-surface-2 transition-colors text-left"
                >
                  <Avatar
                    src={msg.senderProfilePicture}
                    name={`${msg.senderFirstName} ${msg.senderLastName}`}
                    size="sm"
                  />
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="text-body font-semibold text-text-primary">
                        {msg.senderFirstName} {msg.senderLastName}
                      </span>
                      <span className="text-2xs text-text-tertiary">{formatRelativeTime(msg.createdAt)}</span>
                    </div>
                    <p className="text-caption text-text-tertiary mt-0.5 line-clamp-2">{msg.content}</p>
                  </div>
                </button>
              ))}
            </div>
          )}
        </CardBody>
      </Card>
    </div>
  );
}

import { useState } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { FileText, Image, File, Download, Search } from 'lucide-react';
import { Card, CardBody } from '../../components/ui/Card';
import { Input } from '../../components/ui/Input';
import { EmptyState } from '../../components/ui/EmptyState';
import { Button } from '../../components/ui/Button';
import { cn } from '../../lib/cn';
import { useConversationFiles, useWorkspaceMessageFiles } from '../../services/message-hooks';
import { useConversationsList } from '../../services/conversation-hooks';
import { Avatar } from '../../components/ui/Avatar';
import { formatRelativeTime, formatFileSize } from '../../lib/format';

export function SharedFiles() {
  const [searchParams] = useSearchParams();
  const wsId = searchParams.get('ws') ?? '';
  const navigate = useNavigate();
  const [selectedConvId, setSelectedConvId] = useState<string | undefined>();

  const { data: conversations } = useConversationsList(wsId);
  const convFiles = useConversationFiles(wsId, selectedConvId ?? '');
  const wsFiles = useWorkspaceMessageFiles(wsId);
  const filesData = selectedConvId ? convFiles.data : wsFiles.data;
  const isLoading = selectedConvId ? convFiles.isLoading : wsFiles.isLoading;

  const files = filesData?.content ?? [];
  const [filter, setFilter] = useState<'all' | 'images' | 'documents'>('all');

  const filteredFiles = files.filter((f) => {
    if (filter === 'images') return f.mimeType?.startsWith('image/');
    if (filter === 'documents') return f.mimeType && !f.mimeType.startsWith('image/');
    return true;
  });

  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-center gap-4">
        <div className="flex gap-2">
          <button
            type="button"
            onClick={() => setFilter('all')}
            className={cn('rounded-lg px-3 py-1.5 text-body font-medium transition-colors', filter === 'all' ? 'bg-accent-50 text-accent-700 dark:bg-accent-100 dark:text-accent-200' : 'text-text-tertiary hover:text-text-primary')}
          >
            All
          </button>
          <button
            type="button"
            onClick={() => setFilter('images')}
            className={cn('rounded-lg px-3 py-1.5 text-body font-medium transition-colors', filter === 'images' ? 'bg-accent-50 text-accent-700 dark:bg-accent-100 dark:text-accent-200' : 'text-text-tertiary hover:text-text-primary')}
          >
            <Image className="mr-1.5 inline h-4 w-4" />
            Images
          </button>
          <button
            type="button"
            onClick={() => setFilter('documents')}
            className={cn('rounded-lg px-3 py-1.5 text-body font-medium transition-colors', filter === 'documents' ? 'bg-accent-50 text-accent-700 dark:bg-accent-100 dark:text-accent-200' : 'text-text-tertiary hover:text-text-primary')}
          >
            <FileText className="mr-1.5 inline h-4 w-4" />
            Documents
          </button>
        </div>
        {conversations && conversations.content.length > 0 && (
          <select
            value={selectedConvId ?? ''}
            onChange={(e) => setSelectedConvId(e.target.value || undefined)}
            className="rounded-lg border border-border-subtle bg-elevated px-3 py-1.5 text-body text-text-primary"
          >
            <option value="">All Channels</option>
            {conversations.content.map((conv) => (
              <option key={conv.id} value={conv.id}>{conv.name}</option>
            ))}
          </select>
        )}
      </div>

      <Card>
        <CardBody>
          {filteredFiles.length === 0 ? (
            <EmptyState
              icon={<FileText className="h-8 w-8" />}
              title="No shared files"
              description="Files shared in conversations will appear here."
            />
          ) : (
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {filteredFiles.map((msg) => (
                <Card key={msg.id}>
                  <CardBody className="p-3">
                    {msg.mimeType?.startsWith('image/') && msg.fileUrl ? (
                      <img src={msg.fileUrl} alt={msg.fileName ?? ''} className="w-full h-32 object-cover rounded-lg mb-2" />
                    ) : (
                      <div className="flex h-32 items-center justify-center rounded-lg bg-surface-2 mb-2">
                        <File className="h-8 w-8 text-text-tertiary" />
                      </div>
                    )}
                    <p className="text-body font-medium text-text-primary truncate">{msg.fileName ?? 'Untitled'}</p>
                    <div className="flex items-center justify-between mt-1">
                      <span className="text-2xs text-text-tertiary">
                        {msg.fileSize ? formatFileSize(msg.fileSize) : ''}
                        {' ┬À '}
                        {formatRelativeTime(msg.createdAt)}
                      </span>
                      <Button variant="ghost" size="sm" onClick={() => window.open(msg.fileUrl, '_blank')}>
                        <Download className="h-3.5 w-3.5" />
                      </Button>
                    </div>
                    <div className="flex items-center gap-1.5 mt-2 text-2xs text-text-tertiary">
                      <Avatar
                        src={msg.senderProfilePicture}
                        name={`${msg.senderFirstName} ${msg.senderLastName}`}
                        size="xs"
                      />
                      {msg.senderFirstName} {msg.senderLastName}
                    </div>
                  </CardBody>
                </Card>
              ))}
            </div>
          )}
        </CardBody>
      </Card>
    </div>
  );
}

import { useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Modal, type ModalProps } from '../../../components/ui/Modal';
import { Input } from '../../../components/ui/Input';
import { Button } from '../../../components/ui/Button';
import { useCreateAnnouncement } from '../../../services/announcement-hooks';

interface CreateAnnouncementModalProps extends Pick<ModalProps, 'open' | 'onClose'> {}

export function CreateAnnouncementModal({ open, onClose }: CreateAnnouncementModalProps) {
  const [searchParams] = useSearchParams();
  const wsId = searchParams.get('ws') ?? '';
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [isPinned, setIsPinned] = useState(false);
  const createAnnouncement = useCreateAnnouncement(wsId);

  const handleSubmit = async () => {
    if (!title.trim() || !content.trim()) return;
    try {
      await createAnnouncement.mutateAsync({
        title: title.trim(),
        content: content.trim(),
        isPinned,
      });
      setTitle('');
      setContent('');
      setIsPinned(false);
      onClose();
    } catch {
      // handled by mutation
    }
  };

  return (
    <Modal open={open} onClose={onClose} title="Create Announcement">
      <div className="flex flex-col gap-4">
        <Input
          label="Title"
          placeholder="Announcement title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
        />

        <div>
          <label className="text-caption font-medium text-text-primary mb-1.5 block">Content</label>
          <textarea
            placeholder="Write your announcement..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
            rows={5}
            className="w-full rounded-lg border border-border-subtle bg-elevated px-3 py-2 text-body text-text-primary placeholder:text-text-tertiary resize-none focus:outline-none focus:ring-2 focus:ring-accent-500"
          />
        </div>

        <label className="flex items-center gap-2 cursor-pointer">
          <input
            type="checkbox"
            checked={isPinned}
            onChange={(e) => setIsPinned(e.target.checked)}
            className="rounded border-border-subtle"
          />
          <span className="text-body text-text-primary">Pin this announcement</span>
        </label>

        <div className="flex justify-end gap-2 pt-2">
          <Button variant="ghost" onClick={onClose}>Cancel</Button>
          <Button
            variant="primary"
            onClick={handleSubmit}
            disabled={!title.trim() || !content.trim() || createAnnouncement.isPending}
          >
            {createAnnouncement.isPending ? 'Creating...' : 'Create Announcement'}
          </Button>
        </div>
      </div>
    </Modal>
  );
}

import { useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Hash, Lock, Users } from 'lucide-react';
import { Modal, type ModalProps } from '../../../components/ui/Modal';
import { Input } from '../../../components/ui/Input';
import { Button } from '../../../components/ui/Button';
import { useCreateConversation } from '../../../services/conversation-hooks';
import type { ConversationType } from '../../../types/communication';

interface CreateChannelModalProps extends Pick<ModalProps, 'open' | 'onClose'> {}

export function CreateChannelModal({ open, onClose }: CreateChannelModalProps) {
  const [searchParams] = useSearchParams();
  const wsId = searchParams.get('ws') ?? '';
  const [name, setName] = useState('');
  const [topic, setTopic] = useState('');
  const [type, setType] = useState<ConversationType>('WORKSPACE');
  const [isPrivate, setIsPrivate] = useState(false);
  const createConversation = useCreateConversation(wsId);

  const handleSubmit = async () => {
    if (!name.trim()) return;
    try {
      await createConversation.mutateAsync({
        name: name.trim(),
        topic: topic.trim() || undefined,
        type,
        isPrivate,
      });
      setName('');
      setTopic('');
      onClose();
    } catch {
      // handled by mutation
    }
  };

  return (
    <Modal open={open} onClose={onClose} title="Create Channel">
      <div className="flex flex-col gap-4">
        <div>
          <label className="text-caption font-medium text-text-primary mb-1.5 block">Channel Type</label>
          <div className="grid grid-cols-3 gap-2">
            {(['WORKSPACE', 'DEPARTMENT', 'TEAM'] as ConversationType[]).map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => setType(t)}
                className={`flex items-center justify-center gap-2 rounded-lg border px-3 py-2.5 text-body font-medium transition-colors ${
                  type === t
                    ? 'border-accent-500 bg-accent-50 text-accent-700 dark:bg-accent-100 dark:text-accent-200'
                    : 'border-border-subtle text-text-tertiary hover:text-text-primary hover:border-border-default'
                }`}
              >
                {t === 'WORKSPACE' ? <Users className="h-4 w-4" /> : t === 'DEPARTMENT' ? <Hash className="h-4 w-4" /> : <Lock className="h-4 w-4" />}
                {t.charAt(0) + t.slice(1).toLowerCase()}
              </button>
            ))}
          </div>
        </div>

        <Input
          label="Channel Name"
          placeholder="e.g. project-alpha"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
        />

        <Input
          label="Topic (optional)"
          placeholder="What's this channel about?"
          value={topic}
          onChange={(e) => setTopic(e.target.value)}
        />

        <label className="flex items-center gap-2 cursor-pointer">
          <input
            type="checkbox"
            checked={isPrivate}
            onChange={(e) => setIsPrivate(e.target.checked)}
            className="rounded border-border-subtle"
          />
          <span className="text-body text-text-primary">Make private</span>
          <span className="text-caption text-text-tertiary">Only invited members can see this channel</span>
        </label>

        <div className="flex justify-end gap-2 pt-2">
          <Button variant="ghost" onClick={onClose}>Cancel</Button>
          <Button
            variant="primary"
            onClick={handleSubmit}
            disabled={!name.trim() || createConversation.isPending}
          >
            {createConversation.isPending ? 'Creating...' : 'Create Channel'}
          </Button>
        </div>
      </div>
    </Modal>
  );
}

import { useState } from 'react';
import { Plus, X, Loader2, Clock } from 'lucide-react';
import { Card, CardBody } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { Input } from '../../../components/ui/Input';
import { Select } from '../../../components/ui/Select';
import { Badge } from '../../../components/ui/Badge';
import { IconButton } from '../../../components/ui/IconButton';
import { EmptyState } from '../../../components/ui/EmptyState';
import { useToast } from '../../../components/ui/Toast';
import { Can } from '../../auth';
import { useEmployeesList } from '../../../services/employee-hooks';
import { useAttendanceList, useAttendanceStats, useCreateAttendance, useUpdateAttendance, useDeleteAttendance } from '../../../services/attendance-hooks';
import type { CreateAttendanceRequest } from '../../../services/attendance-service';
import { ATTENDANCE_STATUSES, attendanceStatusColor, formatEnum } from './hr-constants';

export function AttendanceTab({ wsId, deptId }: { wsId: string; deptId: string }) {
  const [employeeFilter, setEmployeeFilter] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState<CreateAttendanceRequest>({ date: '', status: 'PRESENT' });

  const { toast } = useToast();
  const { data, isLoading, isError } = useAttendanceList(wsId, deptId);
  const { data: stats } = useAttendanceStats(wsId, deptId);
  const { data: empData } = useEmployeesList(wsId, deptId);
  const createAttendance = useCreateAttendance(wsId, deptId, form.employeeId ?? '');
  const deleteAttendance = useDeleteAttendance(wsId, deptId);

  const records = data?.content ?? [];
  const employees = empData?.content ?? [];

  const filtered = employeeFilter ? records.filter((r) => r.employeeId === employeeFilter) : records;

  const handleCreate = () => {
    if (!form.employeeId) {
      toast({ title: 'Select an employee', tone: 'warning' });
      return;
    }
    createAttendance.mutate(form, {
      onSuccess: () => {
        toast({ title: 'Attendance record created', tone: 'success' });
        setShowForm(false);
        setForm({ date: '', status: 'PRESENT', employeeId: '' });
      },
      onError: () => toast({ title: 'Failed to create record', tone: 'danger' }),
    });
  };

  if (isLoading) {
    return <div className="flex items-center justify-center py-20"><Loader2 className="h-8 w-8 animate-spin text-text-tertiary" /></div>;
  }

  if (isError) {
    return <div className="flex flex-col items-center justify-center py-20 gap-3"><p className="text-body font-medium text-danger-600">Failed to load attendance</p><p className="text-caption text-text-tertiary">Please try again later.</p></div>;
  }

  return (
    <div className="flex flex-col gap-4">
      {stats && (
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="flex flex-col gap-1 p-3 rounded-lg border border-border-subtle">
            <span className="text-2xs text-text-tertiary">Total Records</span>
            <span className="text-section font-bold text-text-primary">{stats.totalRecords}</span>
          </div>
          <div className="flex flex-col gap-1 p-3 rounded-lg border border-border-subtle">
            <span className="text-2xs text-text-tertiary">Present</span>
            <span className="text-section font-bold text-success-600">{stats.presentDays}</span>
          </div>
          <div className="flex flex-col gap-1 p-3 rounded-lg border border-border-subtle">
            <span className="text-2xs text-text-tertiary">Absent</span>
            <span className="text-section font-bold text-danger-600">{stats.absentDays}</span>
          </div>
          <div className="flex flex-col gap-1 p-3 rounded-lg border border-border-subtle">
            <span className="text-2xs text-text-tertiary">Attendance Rate</span>
            <span className="text-section font-bold text-accent-600">{stats.attendanceRate.toFixed(1)}%</span>
          </div>
        </div>
      )}

      <div className="flex items-center justify-between gap-4">
        <div className="flex items-center gap-2 flex-1 max-w-md">
          <Select
            value={employeeFilter}
            onChange={(e) => setEmployeeFilter(e.target.value)}
            containerClassName="flex-1"
            options={[{ value: '', label: 'All Employees' }, ...employees.map((e) => ({ value: e.id, label: `${e.firstName} ${e.lastName}` }))]}
          />
        </div>
        <Can permission="ATTENDANCE_CREATE">
          <Button leftIcon={<Plus />} onClick={() => setShowForm(true)}>Add Record</Button>
        </Can>
      </div>

      {showForm && (
        <Card>
          <CardBody className="flex flex-col gap-3">
            <div className="flex items-center justify-between">
              <h3 className="text-body font-semibold text-text-primary">New Attendance Record</h3>
              <IconButton label="Close" variant="ghost" onClick={() => setShowForm(false)}><X className="h-4 w-4" /></IconButton>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <select value={form.employeeId ?? ''} onChange={(e) => setForm({ ...form, employeeId: e.target.value })}
                className="cx-input h-10 px-3 col-span-2">
                <option value="">Select employee...</option>
                {employees.map((e) => (
                  <option key={e.id} value={e.id}>{e.firstName} {e.lastName}</option>
                ))}
              </select>
              <Input placeholder="Date (YYYY-MM-DD)" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} />
              <Select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value as never })}
                options={ATTENDANCE_STATUSES.map((s) => ({ value: s, label: formatEnum(s) }))} />
              <Input placeholder="Check-in (HH:mm)" value={form.checkInTime ?? ''} onChange={(e) => setForm({ ...form, checkInTime: e.target.value })} />
              <Input placeholder="Check-out (HH:mm)" value={form.checkOutTime ?? ''} onChange={(e) => setForm({ ...form, checkOutTime: e.target.value })} />
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setShowForm(false)}>Cancel</Button>
              <Button onClick={handleCreate} disabled={!form.date}>Create</Button>
            </div>
          </CardBody>
        </Card>
      )}

      {filtered.length === 0 ? (
        <EmptyState icon={<Clock />} title="No attendance records" description="Attendance records for employees will appear here." />
      ) : (
        <div className="space-y-2">
          {filtered.map((r) => (
            <div key={r.id} className="flex items-center gap-4 p-4 rounded-lg border border-border-subtle bg-surface hover:bg-surface-2 transition-colors">
              <div className="flex-1 min-w-0">
                <p className="text-body font-medium text-text-primary">{r.employeeName}</p>
                <p className="text-caption text-text-tertiary">{r.date} ÔÇó {r.employeeNumber}</p>
              </div>
              <div className="hidden sm:flex items-center gap-3 text-2xs text-text-tertiary">
                {r.checkInTime && <span>In: {r.checkInTime}</span>}
                {r.checkOutTime && <span>Out: {r.checkOutTime}</span>}
                {r.workedHours != null && <span>{r.workedHours}h</span>}
              </div>
              <Badge tone={(attendanceStatusColor[r.status] ?? 'neutral') as never} variant="soft">{formatEnum(r.status)}</Badge>
              <Can permission="ATTENDANCE_DELETE">
                <IconButton label="Delete" variant="ghost" size="sm" className="text-danger-600"
                  onClick={() => deleteAttendance.mutate(r.id, { onSuccess: () => toast({ title: 'Record deleted', tone: 'success' }) })}>
                  <X className="h-4 w-4" />
                </IconButton>
              </Can>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

