                  <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-warning-100 text-warning-700 dark:bg-warning-900 dark:text-warning-300 [&>svg]:h-4 [&>svg]:w-4"><FileWarning /></span>
                  <div className="min-w-0">
