import { useState } from 'react';
import { Search, Plus, Check, X, CalendarClock, Pencil } from 'lucide-react';
import { Card, CardBody } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { Input } from '../../../components/ui/Input';
import { Badge } from '../../../components/ui/Badge';
import { IconButton } from '../../../components/ui/IconButton';
import { EmptyState } from '../../../components/ui/EmptyState';
import { useToast } from '../../../components/ui/Toast';
import { Can } from '../../auth';
import { useEmployeesList } from '../../../services/employee-hooks';
import { useEmployeeSkillsList, useCreateEmployeeSkill, useUpdateEmployeeSkill, useDeleteEmployeeSkill, useVerifyEmployeeSkill, useUnverifyEmployeeSkill, useExpiringCertifications } from '../../../services/employee-skill-hooks';
import type { CreateEmployeeSkillRequest, UpdateEmployeeSkillRequest, EmployeeSkillResponse } from '../../../services/employee-skill-service';
import { SKILL_CATEGORIES, skillCategoryLabel, skillLevelColor } from './hr-constants';

export function SkillsTab({ wsId, deptId }: { wsId: string; deptId: string }) {
  const [search, setSearch] = useState('');
  const [selectedEmp, setSelectedEmp] = useState<string | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [editingSkillId, setEditingSkillId] = useState<string | null>(null);
  const [skillForm, setSkillForm] = useState<CreateEmployeeSkillRequest>({
    skillName: '', category: 'TECHNICAL', proficiencyLevel: 'INTERMEDIATE',
  });

  const { toast } = useToast();
  const { data: empData } = useEmployeesList(wsId, deptId);
  const { data: skillData } = useEmployeeSkillsList(wsId, deptId, selectedEmp ?? '');
  const { data: expiringData } = useExpiringCertifications(wsId, deptId);
  const createSkill = useCreateEmployeeSkill(wsId, deptId, selectedEmp ?? '');
  const updateSkill = useUpdateEmployeeSkill(wsId, deptId, selectedEmp ?? '', editingSkillId ?? '');
  const deleteSkill = useDeleteEmployeeSkill(wsId, deptId, selectedEmp ?? '');
  const verifySkill = useVerifyEmployeeSkill(wsId, deptId, selectedEmp ?? '');
  const unverifySkill = useUnverifyEmployeeSkill(wsId, deptId, selectedEmp ?? '');

  const employees = empData?.content ?? [];
  const skills = skillData?.content ?? [];
  const expiringCerts = expiringData ?? [];

  const filteredSkills = skills.filter((s) => {
    if (!search) return true;
    return s.skillName.toLowerCase().includes(search.toLowerCase()) || s.category.toLowerCase().includes(search.toLowerCase());
  });

  const resetForm = () => {
    setShowForm(false);
    setEditingSkillId(null);
    setSkillForm({ skillName: '', category: 'TECHNICAL', proficiencyLevel: 'INTERMEDIATE' });
  };

  const startEdit = (s: EmployeeSkillResponse) => {
    setEditingSkillId(s.id);
    setSkillForm({
      skillName: s.skillName,
      category: s.category,
      proficiencyLevel: s.proficiencyLevel,
      yearsOfExperience: s.yearsOfExperience,
      lastUsedDate: s.lastUsedDate,
      certificationName: s.certificationName,
      certificationIssuer: s.certificationIssuer,
      certificationDate: s.certificationDate,
      certificationExpiration: s.certificationExpiration,
      notes: s.notes,
    });
    setShowForm(true);
  };

  const handleSaveSkill = () => {
    if (!selectedEmp) return;
    if (editingSkillId) {
      const payload: UpdateEmployeeSkillRequest = {
        skillName: skillForm.skillName,
        category: skillForm.category,
        proficiencyLevel: skillForm.proficiencyLevel,
        yearsOfExperience: skillForm.yearsOfExperience,
        lastUsedDate: skillForm.lastUsedDate,
        certificationName: skillForm.certificationName,
        certificationIssuer: skillForm.certificationIssuer,
        certificationDate: skillForm.certificationDate,
        certificationExpiration: skillForm.certificationExpiration,
        notes: skillForm.notes,
      };
      updateSkill.mutate(payload, {
        onSuccess: () => { toast({ title: 'Skill updated', tone: 'success' }); resetForm(); },
        onError: () => toast({ title: 'Failed to update skill', tone: 'danger' }),
      });
    } else {
      createSkill.mutate(skillForm, {
        onSuccess: () => { toast({ title: 'Skill added', tone: 'success' }); resetForm(); },
        onError: () => toast({ title: 'Failed to add skill', tone: 'danger' }),
      });
    }
  };

  return (
    <div className="flex flex-col gap-4">
      {expiringCerts.length > 0 && (
        <Card>
          <CardBody className="flex flex-col gap-2">
            <div className="flex items-center gap-2">
              <CalendarClock className="h-4 w-4 text-warning-600" />
              <span className="text-body font-semibold text-text-primary">Certifications expiring soon</span>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
              {expiringCerts.map((s) => (
                <div key={s.id} className="flex items-start justify-between gap-2 p-3 rounded-lg border border-border-subtle">
                  <div className="min-w-0">
                    <p className="text-caption font-medium text-text-primary">{s.skillName}</p>
                    {s.certificationName && <p className="text-2xs text-text-tertiary">{s.certificationName}</p>}
                  </div>
                  <Badge tone="warning" variant="soft">{s.certificationExpiration ?? '-'}</Badge>
                </div>
              ))}
            </div>
          </CardBody>
        </Card>
      )}

      <div className="flex items-center gap-2">
        <select value={selectedEmp ?? ''} onChange={(e) => { setSelectedEmp(e.target.value || null); setShowForm(false); }}
          className="cx-input h-10 px-3 max-w-xs">
          <option value="">Select an employee...</option>
          {employees.map((e) => (
            <option key={e.id} value={e.id}>{e.firstName} {e.lastName}</option>
          ))}
        </select>
        {selectedEmp && (
          <Can permission="EMPLOYEE_SKILL_CREATE">
            <Button leftIcon={<Plus />} size="sm" onClick={() => { setEditingSkillId(null); setSkillForm({ skillName: '', category: 'TECHNICAL', proficiencyLevel: 'INTERMEDIATE' }); setShowForm(true); }}>Add Skill</Button>
          </Can>
        )}
      </div>

      {!selectedEmp && (
        <EmptyState icon={<Search />} title="Select an employee" description="Choose an employee to view and manage their skills." />
      )}

      {showForm && selectedEmp && (
        <Card>
          <CardBody className="flex flex-col gap-3">
            <div className="flex items-center justify-between">
              <h3 className="text-body font-semibold text-text-primary">{editingSkillId ? 'Edit Skill' : 'Add Skill'}</h3>
              <IconButton label="Close" variant="ghost" onClick={resetForm}><X className="h-4 w-4" /></IconButton>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div className="col-span-2">
                <Input placeholder="Skill Name" value={skillForm.skillName} onChange={(e) => setSkillForm({ ...skillForm, skillName: e.target.value })} />
              </div>
              <select value={skillForm.category} onChange={(e) => setSkillForm({ ...skillForm, category: e.target.value })}
                className="cx-input h-10 px-3">
                {SKILL_CATEGORIES.map((c) => (
                  <option key={c} value={c}>{skillCategoryLabel[c] ?? c}</option>
                ))}
              </select>
              <select value={skillForm.proficiencyLevel} onChange={(e) => setSkillForm({ ...skillForm, proficiencyLevel: e.target.value })}
                className="cx-input h-10 px-3">
                <option value="BEGINNER">Beginner</option>
                <option value="INTERMEDIATE">Intermediate</option>
                <option value="ADVANCED">Advanced</option>
                <option value="EXPERT">Expert</option>
              </select>
              <Input type="number" min={0} placeholder="Years of Experience" value={skillForm.yearsOfExperience != null ? String(skillForm.yearsOfExperience) : ''}
                onChange={(e) => setSkillForm({ ...skillForm, yearsOfExperience: e.target.value === '' ? undefined : Number(e.target.value) })} />
              <Input placeholder="Certification Name" value={skillForm.certificationName ?? ''} onChange={(e) => setSkillForm({ ...skillForm, certificationName: e.target.value })} />
              <Input placeholder="Certification Issuer" value={skillForm.certificationIssuer ?? ''} onChange={(e) => setSkillForm({ ...skillForm, certificationIssuer: e.target.value })} />
              <Input placeholder="Certification Date (YYYY-MM-DD)" value={skillForm.certificationDate ?? ''} onChange={(e) => setSkillForm({ ...skillForm, certificationDate: e.target.value })} />
              <div className="col-span-2">
                <Input placeholder="Certification Expiration (YYYY-MM-DD)" value={skillForm.certificationExpiration ?? ''} onChange={(e) => setSkillForm({ ...skillForm, certificationExpiration: e.target.value })} />
              </div>
              <div className="col-span-2">
                <Input placeholder="Notes" value={skillForm.notes ?? ''} onChange={(e) => setSkillForm({ ...skillForm, notes: e.target.value })} />
              </div>
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={resetForm}>Cancel</Button>
              <Button onClick={handleSaveSkill} disabled={!skillForm.skillName}>{editingSkillId ? 'Save Changes' : 'Add'}</Button>
            </div>
          </CardBody>
        </Card>
      )}

      {selectedEmp && !showForm && (
        <>
          <Input placeholder="Search skills..." leftIcon={<Search />} value={search} onChange={(e) => setSearch(e.target.value)} containerClassName="max-w-sm" />
          {filteredSkills.length === 0 ? (
            <EmptyState icon={<Search />} title="No skills found" description="Add skills to track employee capabilities." />
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
              {filteredSkills.map((s) => (
                <Card key={s.id}>
                  <CardBody className="flex flex-col gap-2">
                    <div className="flex items-start justify-between">
                      <div>
                        <p className="text-body font-medium text-text-primary">{s.skillName}</p>
                        <p className="text-2xs text-text-tertiary">{s.category.replace(/_/g, ' ')}</p>
                      </div>
                      <div className="flex items-center gap-1">
                        {s.verified && <Check className="h-4 w-4 text-success-500" />}
                        <Can permission="EMPLOYEE_SKILL_UPDATE">
                          <IconButton label="Edit skill" variant="ghost" size="sm" onClick={() => startEdit(s)}>
                            <Pencil className="h-4 w-4" />
                          </IconButton>
                        </Can>
                        <Can permission="EMPLOYEE_SKILL_DELETE">
                          <IconButton label="Delete" variant="ghost" size="sm" className="text-danger-600" onClick={() => deleteSkill.mutate(s.id)}>
                            <X className="h-4 w-4" />
                          </IconButton>
                        </Can>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge tone={(skillLevelColor[s.proficiencyLevel] ?? 'neutral') as any} variant="soft">{s.proficiencyLevel}</Badge>
                      {s.yearsOfExperience && <span className="text-2xs text-text-tertiary">{s.yearsOfExperience}y exp</span>}
                    </div>
                    {s.verified ? (
                      <Can permission="EMPLOYEE_SKILL_UPDATE">
                        <Button variant="outline" size="sm" onClick={() => unverifySkill.mutate(s.id)}>Unverify</Button>
                      </Can>
                    ) : (
                      <Can permission="EMPLOYEE_SKILL_UPDATE">
                        <Button variant="outline" size="sm" onClick={() => verifySkill.mutate(s.id)}>Verify</Button>
                      </Can>
                    )}
                    {s.certificationName && (
                      <div className="border-t border-border-subtle pt-2 mt-1">
                        <p className="text-2xs text-text-tertiary">Cert: {s.certificationName}</p>
                        {s.certificationIssuer && <p className="text-2xs text-text-tertiary">Issuer: {s.certificationIssuer}</p>}
                      </div>
                    )}
                  </CardBody>
                </Card>
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
}

import { useState } from 'react';
import {
  ArrowLeft,
  Send,
  Check,
  X,
  CheckCircle2,
  Archive,
  Trash2,
  MessageSquare,
  Paperclip,
  Plus,
  FileText,
  Clock,
  AlertCircle,
  Bell,
  XCircle,
  CheckCheck,
  Info,
  Pencil,
} from 'lucide-react';
import { Card, CardBody, CardHeader, CardTitle } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Badge } from '../../components/ui/Badge';
import { Textarea } from '../../components/ui/Textarea';
import { Timeline, type TimelineItem } from '../../components/ui/Timeline';
import { EmptyState } from '../../components/ui/EmptyState';
import { PageLoader } from '../../components/ui/PageLoader';
import { useToast } from '../../components/ui/Toast';
import { useWorkspaceId } from '../../hooks/useWorkspaceId';
import {
  useHandoverEntry,
  useHandoverComments,
  useHandoverAttachments,
  useHandoverTimeline,
  useSendHandover,
  useAcceptHandover,
  useRejectHandover,
  useCompleteHandover,
  useArchiveHandover,
  useDeleteHandoverEntry,
  useAddHandoverComment,
  useDeleteHandoverComment,
  useDeleteHandoverAttachment,
} from '../../services/handover-hooks';
import type {
  HandoverEntryResponse,
  HandoverStatus,
  HandoverPriority,
  TimelineEventType,
} from '../../services/handover-service';

const statusTone: Record<HandoverStatus, 'neutral' | 'info' | 'success' | 'danger' | 'warning'> = {
  DRAFT: 'neutral',
  PENDING: 'info',
  ACCEPTED: 'warning',
  REJECTED: 'danger',
  COMPLETED: 'success',
  ARCHIVED: 'neutral',
};

const priorityTone: Record<HandoverPriority, 'neutral' | 'success' | 'warning' | 'danger'> = {
  LOW: 'neutral',
  MEDIUM: 'success',
  HIGH: 'warning',
  URGENT: 'danger',
};

const eventTone: Record<TimelineEventType, TimelineItem['tone']> = {
  CREATED: 'accent',
  UPDATED: 'neutral',
  SENT: 'info',
  ACCEPTED: 'success',
  REJECTED: 'danger',
  COMPLETED: 'success',
  ARCHIVED: 'neutral',
  COMMENTED: 'accent',
  ATTACHMENT_ADDED: 'info',
  ATTACHMENT_REMOVED: 'neutral',
  REMINDER_SENT: 'warning',
};

const eventIcon: Record<TimelineEventType, React.ReactNode> = {
  CREATED: <Plus />,
  UPDATED: <Pencil />,
  SENT: <Send />,
  ACCEPTED: <Check />,
  REJECTED: <XCircle />,
  COMPLETED: <CheckCheck />,
  ARCHIVED: <Archive />,
  COMMENTED: <MessageSquare />,
  ATTACHMENT_ADDED: <Paperclip />,
  ATTACHMENT_REMOVED: <Trash2 />,
  REMINDER_SENT: <Bell />,
};

function formatDate(value?: string) {
  if (!value) return 'ÔÇö';
  return new Date(value).toLocaleString();
}

export function HandoverDetailPage({ entryId, onBack }: { entryId: string; onBack: () => void }) {
  const wsId = useWorkspaceId();
  const { toast } = useToast();
  const [comment, setComment] = useState('');
  const [rejectOpen, setRejectOpen] = useState(false);

  const entryQuery = useHandoverEntry(wsId, entryId);
  const commentsQuery = useHandoverComments(wsId, entryId);
  const attachmentsQuery = useHandoverAttachments(wsId, entryId);
  const timelineQuery = useHandoverTimeline(wsId, entryId);

  const sendMutation = useSendHandover(wsId);
  const acceptMutation = useAcceptHandover(wsId);
  const rejectMutation = useRejectHandover(wsId);
  const completeMutation = useCompleteHandover(wsId);
  const archiveMutation = useArchiveHandover(wsId);
  const deleteMutation = useDeleteHandoverEntry(wsId);
  const addCommentMutation = useAddHandoverComment(wsId, entryId);
  const deleteCommentMutation = useDeleteHandoverComment(wsId, entryId);
  const deleteAttachmentMutation = useDeleteHandoverAttachment(wsId, entryId);

  const handleAction = async (fn: () => Promise<unknown>, success: string) => {
    try {
      await fn();
      toast({ title: success, tone: 'success' });
    } catch (err) {
      toast({
        title: 'Action failed',
        description: (err as { message?: string })?.message ?? 'An unexpected error occurred.',
        tone: 'danger',
      });
    }
  };

  if (entryQuery.isLoading) return <PageLoader />;
  if (entryQuery.isError || !entryQuery.data) {
    return (
      <div className="flex flex-col items-center justify-center py-20 gap-4">
        <AlertCircle className="h-12 w-12 text-danger-500" />
        <p className="text-body font-medium text-text-primary">Failed to load handover</p>
        <p className="text-caption text-text-tertiary">{(entryQuery.error as { message?: string })?.message ?? 'An unexpected error occurred.'}</p>
        <Button onClick={onBack} leftIcon={<ArrowLeft />}>Back to Handovers</Button>
      </div>
    );
  }

  const entry = entryQuery.data;

  return (
    <div className="flex flex-col gap-6">
      <div className="flex items-center justify-between gap-3">
        <button
          type="button"
          onClick={onBack}
          className="flex h-9 w-9 items-center justify-center rounded-lg border border-border-subtle text-text-secondary hover:bg-surface-2 hover:text-text-primary transition-colors"
          aria-label="Back"
        >
          <ArrowLeft className="h-4 w-4" />
        </button>
        <div className="flex flex-wrap items-center justify-end gap-2">
          {entry.status === 'DRAFT' && (
            <>
              <Button
                size="sm"
                leftIcon={<Send />}
                loading={sendMutation.isPending}
                onClick={() => handleAction(() => sendMutation.mutateAsync({ entryId }), 'Handover sent')}
              >
                Send
              </Button>
              <Button
                size="sm"
                variant="outline"
                leftIcon={<Trash2 />}
                loading={deleteMutation.isPending}
                onClick={() => handleAction(() => deleteMutation.mutateAsync(entryId), 'Handover deleted')}
              >
                Delete
              </Button>
            </>
          )}
          {entry.status === 'PENDING' && (
            <>
              <Button
                size="sm"
                variant="success"
                leftIcon={<Check />}
                loading={acceptMutation.isPending}
                onClick={() => handleAction(() => acceptMutation.mutateAsync({ entryId }), 'Handover accepted')}
              >
                Accept
              </Button>
              <Button
                size="sm"
                variant="outline"
                leftIcon={<X />}
                onClick={() => setRejectOpen(true)}
              >
                Reject
              </Button>
            </>
          )}
          {entry.status === 'ACCEPTED' && (
            <Button
              size="sm"
              leftIcon={<CheckCircle2 />}
              loading={completeMutation.isPending}
              onClick={() => handleAction(() => completeMutation.mutateAsync({ entryId }), 'Handover completed')}
            >
              Mark Complete
            </Button>
          )}
          {entry.status !== 'ARCHIVED' && (
            <Button
              size="sm"
              variant="outline"
              leftIcon={<Archive />}
              loading={archiveMutation.isPending}
              onClick={() => handleAction(() => archiveMutation.mutateAsync({ entryId }), 'Handover archived')}
            >
              Archive
            </Button>
          )}
        </div>
      </div>

      {rejectOpen && (
        <RejectPanel
          entryId={entryId}
          onCancel={() => setRejectOpen(false)}
          onSubmitted={() => {
            setRejectOpen(false);
            toast({ title: 'Handover rejected', tone: 'success' });
          }}
        />
      )}

      <div className="flex flex-col gap-4">
        <div className="flex flex-wrap items-center gap-2">
          <h1 className="text-page font-semibold text-text-primary">{entry.title}</h1>
          <Badge tone={statusTone[entry.status]} variant="soft">{entry.status}</Badge>
          <Badge tone={priorityTone[entry.priority]} variant="outline">{entry.priority}</Badge>
        </div>
        <p className="whitespace-pre-wrap text-body leading-relaxed text-text-secondary">{entry.content}</p>
      </div>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetaBox label="Sender" value={`${entry.sender.firstName} ${entry.sender.lastName}`} sub={entry.sender.email} />
        <MetaBox label="Receiver" value={`${entry.receiver.firstName} ${entry.receiver.lastName}`} sub={entry.receiver.email} />
        <MetaBox label="Due date" value={formatDate(entry.dueDate)} />
        <MetaBox label="Project" value={entry.projectId} sub={`Created ${formatDate(entry.createdAt)}`} />
      </div>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
        <div className="flex flex-col gap-6 lg:col-span-2">
          <CommentsCard
            entryId={entryId}
            comment={comment}
            setComment={setComment}
            onAdd={() => {
              if (!comment.trim()) return;
              handleAction(
                () => addCommentMutation.mutateAsync({ content: comment.trim() }).then(() => setComment('')),
                'Comment added',
              );
            }}
            loading={addCommentMutation.isPending}
          />

          <AttachmentsCard entryId={entryId} onDelete={(id) => handleAction(() => deleteAttachmentMutation.mutateAsync(id), 'Attachment removed')} />
        </div>

        <Card>
          <CardHeader><CardTitle>Timeline</CardTitle></CardHeader>
          <CardBody>
            {timelineQuery.isLoading ? (
              <PageLoader />
            ) : !timelineQuery.data || timelineQuery.data.length === 0 ? (
              <EmptyState icon={<Clock />} title="No activity yet" />
            ) : (
              <Timeline
                items={timelineQuery.data.map((ev) => ({
                  id: ev.id,
                  tone: eventTone[ev.eventType] ?? 'neutral',
                  icon: eventIcon[ev.eventType],
                  title: ev.description,
                  timestamp: formatDate(ev.occurredAt),
                }))}
              />
            )}
          </CardBody>
        </Card>
      </div>
    </div>
  );
}

function MetaBox({ label, value, sub }: { label: string; value: string; sub?: string }) {
  return (
    <div className="rounded-lg border border-border-subtle bg-surface-2 p-4">
      <p className="text-2xs font-medium text-text-tertiary">{label}</p>
      <p className="mt-1 truncate text-body font-semibold text-text-primary" title={value}>{value}</p>
      {sub && <p className="mt-0.5 truncate text-caption text-text-tertiary" title={sub}>{sub}</p>}
    </div>
  );
}

function RejectPanel({
  entryId,
  onCancel,
  onSubmitted,
}: {
  entryId: string;
  onCancel: () => void;
  onSubmitted: () => void;
}) {
  const wsId = useWorkspaceId();
  const rejectMutation = useRejectHandover(wsId);
  const [reason, setReason] = useState('');
  const { toast } = useToast();

  return (
    <div className="rounded-xl border border-danger-200 dark:border-danger-800 bg-danger-50 dark:bg-danger-900/40 p-4">
      <div className="flex items-center gap-2 mb-3">
        <XCircle className="h-4 w-4 text-danger-600 dark:text-danger-300" />
        <p className="text-body font-medium text-danger-700 dark:text-danger-200">Reject handover</p>
      </div>
      <Textarea
        placeholder="Reason for rejection (optional)"
        value={reason}
        onChange={(e) => setReason(e.target.value)}
      />
      <div className="mt-3 flex items-center justify-end gap-2">
        <Button size="sm" variant="outline" onClick={onCancel}>Cancel</Button>
        <Button
          size="sm"
          variant="danger"
          loading={rejectMutation.isPending}
          onClick={async () => {
            try {
              await rejectMutation.mutateAsync({ entryId, data: reason.trim() ? { reason: reason.trim() } : undefined });
              onSubmitted();
            } catch (err) {
              toast({
                title: 'Failed to reject handover',
                description: (err as { message?: string })?.message ?? 'An unexpected error occurred.',
                tone: 'danger',
              });
            }
          }}
        >
          Reject
        </Button>
      </div>
    </div>
  );
}

