  const attachmentsQuery = useHandoverAttachments(wsId, entryId);
  const { toast } = useToast();

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2"><Paperclip className="h-4 w-4" /> Attachments</CardTitle>
