import { mapUserToMember } from './members-types';

type ViewMode = 'grid' | 'table';
type SortKey = 'name' | 'joinedDate' | 'lastActive';

function statusTone(status: string): 'success' | 'warning' | 'neutral' | 'danger' {
  switch (status) {
    case 'ACTIVE': return 'success';
    case 'SUSPENDED': return 'danger';
    case 'INACTIVE': return 'warning';
    default: return 'neutral';
  }
}

function roleLabel(role: string): string {
  return role.charAt(0).toUpperCase() + role.slice(1).replace(/_/g, ' ');
}

function formatDate(dateStr: string): string {
  if (!dateStr) return 'ÔÇö';
  return new Date(dateStr).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
}

export function MembersPage() {
  const { toast } = useToast();
  const wsId = useWorkspaceId();
  const [viewMode, setViewMode] = useState<ViewMode>('grid');
  const [search, setSearch] = useState('');
  const [filters, setFilters] = useState<MemberFilters>({});
  const [sortBy, setSortBy] = useState<SortKey>('name');

  const { data: userData, isLoading, isError } = useUsersList();

  const allMembers = useMemo(() => {
    return (userData ?? []).map(mapUserToMember);
  }, [userData]);

  const filteredMembers = useMemo(() => {
    let result = allMembers;

    if (search) {
      const q = search.toLowerCase();
      result = result.filter(
        (m) =>
          m.name.toLowerCase().includes(q) ||
          m.email.toLowerCase().includes(q) ||
          m.role.toLowerCase().includes(q),
      );
    }

    if (filters.department) {
      result = result.filter((m) => m.department === filters.department);
    }
    if (filters.team) {
      result = result.filter((m) => m.team === filters.team);
    }
    if (filters.role) {
      result = result.filter((m) => m.role === filters.role);
    }
    if (filters.status) {
      result = result.filter((m) => m.status === filters.status);
    }

    result = [...result].sort((a, b) => {
      switch (sortBy) {
        case 'joinedDate':
          return new Date(b.createdAt ?? 0).getTime() - new Date(a.createdAt ?? 0).getTime();
        case 'lastActive':
          return new Date(b.lastActive ?? 0).getTime() - new Date(a.lastActive ?? 0).getTime();
        case 'name':
        default:
          return a.name.localeCompare(b.name);
      }
    });

    return result;
  }, [allMembers, search, filters, sortBy]);

  const departments = Array.from(new Set(allMembers.map((m) => m.department))).filter(d => d !== 'ÔÇö');
  const teams = Array.from(new Set(allMembers.map((m) => m.team))).filter(t => t !== 'ÔÇö');
  const roles = Array.from(new Set(allMembers.map((m) => m.role)));

  /* ---- Loading state ---- */
  if (isLoading) {
    return (
      <div className="flex flex-col gap-6">
        <div>
          <h1 className="text-page font-semibold text-text-primary">Members</h1>
          <p className="text-body text-text-secondary">Manage all members inside the current workspace.</p>
        </div>
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
          {[1, 2, 3, 4].map(i => (
            <Card key={i}><CardBody><Skeleton className="h-48 w-full" /></CardBody></Card>
          ))}
        </div>
      </div>
    );
  }

  /* ---- Error state ---- */
  if (isError) {
    return (
      <div className="flex flex-col gap-6">
        <div>
          <h1 className="text-page font-semibold text-text-primary">Members</h1>
          <p className="text-body text-text-secondary">Manage all members inside the current workspace.</p>
        </div>
        <EmptyState
          icon={<Users className="h-6 w-6" />}
          title="Failed to load members"
          description="Unable to load members from backend."
        />
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6">
      {/* Header */}
      <div className="flex flex-col gap-1.5">
        <h1 className="text-page font-semibold text-text-primary">Members</h1>
        <p className="text-body text-text-secondary">
          Manage all members inside the current workspace.
        </p>
      </div>

      {/* Toolbar */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-1 flex-col gap-2 sm:flex-row sm:gap-2">
          <div className="flex-1">
            <Input
              placeholder="Search by name, email, role..."
              leftIcon={<Search />}
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              containerClassName="w-full"
            />
          </div>

          <Dropdown
            trigger={
              <Button variant="outline" size="md">
                Department
                <ChevronDown className="h-3.5 w-3.5" />
              </Button>
            }
            items={[
              { label: 'All Departments', onClick: () => setFilters((f) => ({ ...f, department: undefined })) },
              { divider: true },
              ...departments.map((d) => ({
                label: d,
                onClick: () => setFilters((f) => ({ ...f, department: d })),
              })),
            ]}
          />

          <Dropdown
            trigger={
              <Button variant="outline" size="md">
                Team
                <ChevronDown className="h-3.5 w-3.5" />
              </Button>
            }
            items={[
              { label: 'All Teams', onClick: () => setFilters((f) => ({ ...f, team: undefined })) },
              { divider: true },
              ...teams.map((t) => ({
                label: t,
                onClick: () => setFilters((f) => ({ ...f, team: t })),
              })),
            ]}
          />

          <Dropdown
            trigger={
              <Button variant="outline" size="md">
                Role
                <ChevronDown className="h-3.5 w-3.5" />
              </Button>
            }
            items={[
              { label: 'All Roles', onClick: () => setFilters((f) => ({ ...f, role: undefined })) },
              { divider: true },
              ...roles.map((r) => ({
                label: roleLabel(r),
                onClick: () => setFilters((f) => ({ ...f, role: r })),
              })),
            ]}
          />

          <Dropdown
            trigger={
              <Button variant="outline" size="md">
                Sort
                <ChevronDown className="h-3.5 w-3.5" />
              </Button>
            }
            items={[
              { label: 'Name (A-Z)', onClick: () => setSortBy('name') },
              { label: 'Recently Joined', onClick: () => setSortBy('joinedDate') },
              { label: 'Last Active', onClick: () => setSortBy('lastActive') },
            ]}
          />
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <div className="flex items-center gap-1 border border-border-subtle rounded-lg p-1">
            <IconButton
              label="Grid view"
              variant={viewMode === 'grid' ? 'solid' : 'ghost'}
              size="sm"
              onClick={() => setViewMode('grid')}
              className="h-8 w-8"
            >
              <LayoutGrid className="h-4 w-4" />
            </IconButton>
            <IconButton
              label="Table view"
              variant={viewMode === 'table' ? 'solid' : 'ghost'}
              size="sm"
              onClick={() => setViewMode('table')}
              className="h-8 w-8"
            >
              <LayoutList className="h-4 w-4" />
            </IconButton>
          </div>

          <Button leftIcon={<UserPlus />} onClick={() => toast({ title: 'Add Member', description: 'Navigate to user creation form.', tone: 'info' })}>
            Invite Member
          </Button>
        </div>
      </div>

      {/* Content */}
      {filteredMembers.length === 0 ? (
        <EmptyState
          icon={<Users />}
          title="No members found"
          description="Try adjusting your search or filters to find members."
        />
      ) : viewMode === 'grid' ? (
        <MembersGridView members={filteredMembers} />
      ) : (
        <MembersTableView members={filteredMembers} />
      )}
    </div>
  );
}

