}

const sessions: Session[] = [
  { id: '1', device: 'MacBook Pro 16"', browser: 'Chrome 125', os: 'macOS 14.5', location: 'San Francisco, US', lastActivity: 'Now', isCurrent: true, ip: '192.168.1.42' },
