export function TeamsPage() {
  const [query, setQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | TeamStatus>('all');
  const [sortBy, setSortBy] = useState<SortKey>('name');
  const [view, setView] = useState<ViewMode>('grid');
  const [selected, setSelected] = useState<Team | null>(null);
  const [modal, setModal] = useState<{ kind: 'create' } | { kind: 'edit'; team: Team } | { kind: 'archive'; team: Team } | null>(null);

  const { teams: allTeamSummaries, departments, isLoading, isError } = useTeamsData();

  const allTeams = useMemo(() => {
    return (allTeamSummaries ?? []).map((t) =>
      mapTeamSummaryToTeam(t, t.departmentName ?? t.departmentId)
    );
  }, [allTeamSummaries]);

  const filtered = useMemo(() => {
    let list = allTeams.filter((t) => {
      const q = query.toLowerCase();
      const matchesQuery = !query || t.name.toLowerCase().includes(q) || (t.description ?? '').toLowerCase().includes(q);
      const matchesStatus = statusFilter === 'all' || t.status === statusFilter;
      return matchesQuery && matchesStatus;
    });

    list = [...list].sort((a, b) => {
      switch (sortBy) {
        case 'name': return a.name.localeCompare(b.name);
        case 'members': return (b.memberCount ?? 0) - (a.memberCount ?? 0);
        case 'created': return new Date(b.createdAt ?? 0).getTime() - new Date(a.createdAt ?? 0).getTime();
        default: return 0;
      }
    });

    return list;
  }, [allTeams, query, statusFilter, sortBy]);

  const PAGE_SIZE = 12;
  const [page, setPage] = useState(1);
  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const paginated = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  function handleAction(kind: 'view' | 'edit' | 'archive', team: Team) {
    if (kind === 'view') setSelected(team);
    else if (kind === 'edit') setModal({ kind: 'edit', team });
    else if (kind === 'archive') setModal({ kind: 'archive', team });
  }

  /* ---- Loading state ---- */
  if (isLoading) {
    return (
      <div className="flex flex-col gap-6 animate-fade-in">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <Skeleton className="h-8 w-64" />
            <Skeleton className="h-4 w-96 mt-2" />
          </div>
        </div>
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {[1, 2, 3].map(i => <Skeleton key={i} className="h-48 rounded-xl" />)}
        </div>
      </div>
    );
  }

  /* ---- Error state ---- */
  if (isError) {
    return (
      <Card>
        <CardBody className="py-16">
          <EmptyState
            icon={<Users className="h-6 w-6" />}
            title="Failed to load teams"
            description="Unable to load teams from backend."
          />
        </CardBody>
      </Card>
    );
  }

  return (
    <div className="flex flex-col gap-8 animate-fade-in">
      {/* Page header */}
      <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-display font-semibold text-text-primary">Teams</h1>
            <Badge tone="success" variant="soft" dot>Active</Badge>
          </div>
          <p className="mt-1 text-body text-text-secondary">Manage operational teams within your organization.</p>
          <div className="mt-3 flex flex-wrap items-center gap-2">
            <Badge tone="accent" variant="soft" dot>Teams</Badge>
            <Badge tone="neutral" variant="soft">{allTeams.length} teams</Badge>
            <Badge tone="neutral" variant="soft">{departments.length} departments</Badge>
          </div>
        </div>
        <div className="flex flex-wrap gap-2 shrink-0">
          <Can permission="TEAM_CREATE">
            <Button leftIcon={<Plus />} onClick={() => setModal({ kind: 'create' })}>Create Team</Button>
          </Can>
        </div>
      </div>

      {/* Summary stats */}
      <div>
        <SectionHeader title="Team Statistics" description="Key metrics across all teams" />
        <div className="grid gap-4 grid-cols-2 sm:grid-cols-3 lg:grid-cols-4">
          <StatCard label="Teams" value={allTeams.length} sub="in workspace" icon={Users} tone="accent" />
          <StatCard label="Members" value={allTeams.reduce((a, t) => a + (t.memberCount ?? 0), 0)} sub="across all teams" icon={Users} tone="info" />
          <StatCard label="Departments" value={departments.length} sub="with teams" icon={FolderKanban} tone="neutral" />
        </div>
      </div>

      {/* Teams + toolbar */}
      <div>
        <SectionHeader
          title="All Teams"
          description="Browse and manage all teams"
          action={<ViewToggle mode={view} onChange={setView} modes={[{ id: 'grid', label: 'Grid' }, { id: 'list', label: 'List' }]} />}
        />

        {/* Toolbar */}
        <div className="mb-4 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
          <div className="relative w-full lg:max-w-xs">
            <Search className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-text-tertiary" />
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search teams..."
              className="cx-input h-10 pl-9 w-full"
            />
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <FilterSelect label="Status" value={statusFilter} onChange={(v) => setStatusFilter(v as 'all' | TeamStatus)} options={['all', 'ACTIVE', 'ARCHIVED']} />
            <FilterSelect label="Sort" value={sortBy} onChange={(v) => setSortBy(v as SortKey)} options={['name', 'members', 'created']} />
          </div>
        </div>

        {paginated.length === 0 ? (
          <Card>
            <CardBody className="py-16">
              <EmptyState
                icon={<Users className="h-6 w-6" />}
                title="No teams found"
                description={query ? 'Try adjusting your search.' : 'No teams have been created yet.'}
              />
            </CardBody>
          </Card>
        ) : view === 'grid' ? (
          <div className="grid gap-4 sm:grid-cols-2 2xl:grid-cols-3">
            {paginated.map((t) => (
              <TeamCard key={t.id} team={t} onSelect={setSelected} />
